window.DATA = {"exo": {"F0": {"id": "F0", "titre": "Flash · Quelle source croyez-vous ?", "mode": "Équipe", "duree": 5, "chap": "Carnet · chapitre 1", "situation": ["Trois affirmations sur l'authentification forte (toutes fictives) :", "A. Brochure d'un éditeur : « Notre outil réduit les incidents de 99 %. » Aucune méthode.", "B. Rapport d'une agence publique : « −30 % de comptes compromis avec une authentification forte » ; 120 organisations, méthode publiée.", "C. Message anonyme sur un forum : « Mon cousin dit que ça ne sert à rien. »"], "taches": ["Classez A, B, C de la plus à la moins fiable.", "Donnez une raison pour chacune.", "Que vérifieriez-vous avant de citer B ?"], "livrable": "", "corr": {"methode": ["Qui parle, et pourquoi ?", "La méthode est-elle visible ?", "Peut-on recouper ?"], "rows": [["Classement", "B, puis A, puis C"], ["B", "Agence publique, méthode publiée, échantillon indiqué : la plus solide"], ["A", "Intérêt commercial, aucune méthode : à citer comme « position de l'éditeur »"], ["C", "Anonyme, sans source : à écarter"], ["Avant de citer B", "La date, l'échantillon, la définition de « compromis », d'autres sources qui concordent"]], "erreurs": ["Croire un chiffre précis (99 %) plus qu'une méthode.", "Écarter A sans l'utiliser : il montre la position du fournisseur."]}}, "EX1": {"id": "EX1", "titre": "Choisir et formuler votre question de décision", "mode": "Équipes", "duree": 25, "chap": "Carnet · chapitre 1", "situation": ["La directrice de TransLor (PME de 120 salariés, entreprise fictive) vous confie un état de l'art pour éclairer une décision informatique.", "Choisissez un sujet dans la liste (page « Sujets » de l'application, QR sur la diapositive).", "Vous défendrez votre travail devant un jury à la fin du cours."], "taches": ["Choisissez un sujet dans la liste.", "Reformulez-le en question de décision : « Faut-il … chez TransLor, selon quels critères ? »", "Écrivez 4 critères de comparaison (par exemple coût, sécurité, facilité d'usage, délai).", "Écrivez 3 mots-clés en français et leur traduction en anglais.", "Notez une chose que vous ne savez pas encore."], "livrable": "Votre question de décision, 4 critères et 3 mots-clés dans le carnet.", "corr": {"methode": ["Un thème n'est pas une question : il faut une décision.", "Les critères sont des mots que l'on peut comparer.", "Les mots-clés viennent de la question, pas du hasard."], "cols": ["Faible", "Bon (exemple)"], "widths": [3.0, 6.0], "rows": [["« Les passkeys »", "« Faut-il remplacer les mots de passe par des passkeys chez TransLor, selon le coût, la sécurité, la facilité d'usage et la compatibilité ? »"], ["« Le cloud, c'est mieux ? »", "« Faut-il héberger la messagerie dans un cloud public, chez un hébergeur local ou en interne, selon le coût, la sécurité et la reprise après panne ? »"], ["Critères : « bien », « moderne »", "Critères comparables : coût annuel, délai de déploiement, risque résiduel, satisfaction des utilisateurs"], ["Mots-clés : « sécurité »", "« passkeys » OR « passwordless », « authentification » OR « authentication »"]], "erreurs": ["Un sujet trop large : on ne finira pas.", "Un sujet sans littérature : vérifiez en deux minutes que vous trouvez au moins cinq résultats sérieux.", "Écrire la réponse d'avance : la question reste ouverte."]}}, "EX6": {"id": "EX6", "titre": "Rédiger une note de synthèse d'une page", "mode": "Individuel", "duree": 20, "chap": "Carnet · chapitre 2", "situation": ["Extrait d'un rapport interne (fictif) sur les sauvegardes de TransLor :", "La sauvegarde est faite chaque nuit sur un disque unique, dans la salle serveur. Le disque a trois ans. Un test de restauration en juin a pris 9 heures. L'administrateur estime la probabilité d'une panne de disque à 10 % par an. Une journée d'arrêt coûterait environ 40 000 € (hypothèse inventée). Le prestataire propose une copie hors site pour 150 € par mois, avec restauration en 3 heures."], "taches": ["Écrivez la conclusion en une phrase.", "Donnez trois arguments chiffrés.", "Nommez un risque ou une réserve.", "Formulez la décision demandée, avec une date.", "Relisez : le lecteur peut-il agir sans vous poser de question ?"], "livrable": "Une note de synthèse de 6 lignes maximum.", "corr": {"methode": ["Conclusion d'abord.", "Trois arguments, chacun avec un chiffre.", "Une réserve honnête.", "Une décision demandée et une date."], "rows": [["Conclusion", "Ajouter une copie hors site des sauvegardes"], ["Argument 1", "Disque unique de trois ans : risque de panne estimé à 10 % par an"], ["Argument 2", "Restauration actuelle : 9 h, contre 3 h avec la copie hors site"], ["Argument 3", "Coût : 150 × 12 = 1 800 € par an ; perte attendue sans copie : 10 % × 40 000 = 4 000 € par an"], ["Réserve", "La probabilité est une estimation de l'administrateur ; le coût d'un arrêt est une hypothèse"], ["Décision demandée", "Valider 1 800 € par an avant la fin du mois"]], "erreurs": ["Raconter l'historique au lieu de conclure.", "Écrire « coûteux » ou « rapide » sans chiffre.", "Oublier la décision demandée et la date."], "modele": ["Objet : Décision avant fin du mois : copie hors site des sauvegardes", "Je recommande d'ajouter une copie hors site (1 800 € par an). Le disque unique a trois ans, avec une panne estimée à 10 % par an ; la restauration prendrait 9 h, contre 3 h avec la copie. Une journée d'arrêt coûterait environ 40 000 € (hypothèse), soit une perte attendue de 4 000 € par an. Réserve : la probabilité est une estimation à confirmer par un test. Décision demandée : valider avant le 30."], "retenir": "Une note de synthèse se lit en une minute : conclusion, trois arguments chiffrés, réserve, décision demandée."}}, "EX7": {"id": "EX7", "titre": "Décomposer une question en mots-clés", "mode": "Binôme", "duree": 25, "chap": "Carnet · chapitre 3", "situation": ["Question d'exemple : « Faut-il activer les mises à jour automatiques sur tous les postes de TransLor ? »", "Un moteur de recherche ne comprend pas une phrase : il cherche des mots. Il faut les choisir."], "taches": ["Soulignez les 3 concepts clés de la question.", "Pour chaque concept, écrivez des synonymes en français et en anglais.", "Repérez les sigles ou termes techniques utiles.", "Assemblez une requête avec guillemets et OR.", "Appliquez la même méthode à votre propre question (EX1)."], "livrable": "Un tableau : concepts, synonymes français et anglais, requête.", "corr": {"methode": ["Un concept = un mot ou une expression.", "Un synonyme par ligne, en français et en anglais.", "Guillemets pour les expressions, OR entre synonymes."], "cols": ["Concept", "Synonymes (FR / EN)"], "widths": [2.6, 6.2], "rows": [["Mises à jour automatiques", "« mise à jour automatique » OR « automatic update » OR « auto-update »"], ["Correctifs de sécurité", "correctif OR « patch » OR « security update »"], ["Postes de travail", "« poste de travail » OR « endpoint » OR « workstation »"], ["Requête assemblée", "(« mise à jour automatique » OR « automatic update ») (« poste de travail » OR « endpoint ») sécurité OR security"]], "erreurs": ["Taper la question entière : le moteur en tire des résultats flous.", "Oublier l'anglais : on perd une grande part de la littérature technique.", "Des mots trop généraux (« sécurité » seul)."]}}, "EX8": {"id": "EX8", "titre": "Chercher dans Google Scholar avec des opérateurs", "mode": "Individuel, ordinateur", "duree": 35, "chap": "Carnet · chapitre 3", "situation": ["Ouvrez Google Scholar (ou Semantic Scholar) avec la requête de votre question (EX7).", "Une recherche doit pouvoir être refaite : notez la requête exacte et la date."], "taches": ["Lancez une requête simple et notez le nombre de résultats.", "Précisez avec guillemets, OR, tiret (pour exclure) et le filtre de dates (5 dernières années).", "Comparez le nombre de résultats avant et après.", "Relevez 5 résultats utiles : titre, auteurs, année, type de document.", "Pour chacun : article de revue, actes de conférence, rapport, thèse, page commerciale ?"], "livrable": "La requête finale, la date, et 5 résultats notés.", "corr": {"methode": ["Partir large, puis préciser.", "Comparer avant et après : une bonne requête réduit le nombre de résultats sans perdre l'essentiel.", "Noter la trace de la recherche."], "cols": ["Étape", "Ce qui est attendu"], "widths": [2.2, 6.6], "rows": [["Requête simple", "Souvent des dizaines de milliers de résultats : inutilisable telle quelle"], ["Requête précisée", "Quelques centaines ou milliers : on peut lire les premières pages"], ["Exemple d'opérateurs", "« authentification forte » OR « multi-factor authentication » -banque, avec le filtre « depuis 2021 » (menu de gauche)"], ["Natures à repérer", "Article de revue, actes de conférence, rapport, thèse, page commerciale, presse"], ["Trace", "Requête, date, nombre de résultats : une recherche doit pouvoir être refaite"]], "erreurs": ["Ne lire que le premier résultat.", "Ne pas noter la requête : impossible de la justifier ou de la refaire.", "Tout garder sans regarder la nature du document."]}}, "F3": {"id": "F3", "titre": "Flash · Quel opérateur de recherche ?", "mode": "Individuel", "duree": 5, "chap": "Carnet · chapitre 3", "situation": ["Pour chaque besoin, quel opérateur utilisez-vous dans Google Scholar ?"], "taches": ["Chercher l'expression exacte zero trust.", "Accepter « cloud » ou « nuage ».", "Exclure le mot « bitcoin » des résultats.", "Ne garder que les cinq dernières années."], "livrable": "", "corr": {"methode": ["Guillemets : expression exacte.", "OR : l'un ou l'autre.", "Tiret : exclure.", "Filtre de dates : menu de gauche."], "rows": [["1. Expression exacte", "« zero trust » (entre guillemets)"], ["2. Synonymes", "cloud OR nuage"], ["3. Exclure", "-bitcoin (tiret collé au mot)"], ["4. Période", "Filtre de dates, ou « depuis 20XX » dans le menu de gauche"]], "erreurs": ["Mettre un espace entre le tiret et le mot.", "Oublier que OR s'écrit en majuscules."]}}, "EX9": {"id": "EX9", "titre": "Trouver deux sources institutionnelles", "mode": "Équipes", "duree": 25, "chap": "Carnet · chapitre 3", "situation": ["Pour votre question, cherchez deux documents publiés par des organismes publics ou de normalisation.", "Pistes : ANSSI et CNIL (France), ENISA (Europe), NIST (États-Unis), ISO et AFNOR (normes, parfois payantes)."], "taches": ["Trouvez deux documents utiles à votre question.", "Notez pour chacun : organisme, titre, date, version, adresse.", "Résumez en une phrase ce qu'il dit sur votre question.", "Est-ce une recommandation, une norme, une obligation légale ou un rapport d'étude ?", "Vérifiez la date : est-elle adaptée au sujet ?"], "livrable": "Deux références complètes avec une phrase de synthèse chacune.", "corr": {"methode": ["Chercher d'abord sur le site de l'organisme.", "Noter date et version.", "Distinguer recommandation, norme et loi."], "cols": ["Type", "Ce que c'est, et exemple"], "widths": [2.4, 6.4], "rows": [["Recommandation", "Guide de bonnes pratiques : pas obligatoire, mais fait référence (guides d'une agence nationale, par exemple)"], ["Norme", "Texte consensuel de normalisation (ISO, AFNOR) : applicable si on s'y engage, parfois payante"], ["Obligation légale", "Loi ou règlement : s'impose (par exemple le RGPD pour les données personnelles)"], ["Rapport d'étude", "Observations ou statistiques : à lire avec la méthode et la date"]], "erreurs": ["Prendre une recommandation pour une obligation.", "Citer sans date ni version : le document a peut-être été remplacé.", "Citer un lien qui ne fonctionnera plus : enregistrer le document (Zotero)."]}}, "EX10": {"id": "EX10", "titre": "Atelier Zotero : enregistrer et citer", "mode": "Individuel, ordinateur", "duree": 30, "chap": "Carnet · chapitre 3", "situation": ["Zotero est un outil gratuit de gestion de références. Version de bureau avec extension de navigateur (Zotero Connector).", "Si l'installation est impossible sur votre poste, utilisez un tableur : auteur, année, titre, lien."], "taches": ["Installez Zotero et son extension, ou ouvrez la version web (zotero.org).", "Depuis Google Scholar, enregistrez 5 références d'un clic sur l'extension.", "Vérifiez dans Zotero : auteurs, année, titre, adresse.", "Créez un dossier et deux étiquettes (par exemple « retenue », « à vérifier »).", "Générez une bibliographie (clic droit, « Créer une bibliographie ») dans un style au choix."], "livrable": "Votre bibliographie de 5 références générée par Zotero.", "corr": {"methode": ["Un clic enregistre la référence.", "Toujours vérifier les champs importés.", "Classer dès l'enregistrement."], "cols": ["Geste", "Résultat attendu"], "widths": [3.0, 5.8], "rows": [["Enregistrer", "Icône de l'extension dans le navigateur : la référence apparaît dans la bibliothèque"], ["Vérifier", "Les champs vides (année, auteurs) se complètent à la main"], ["Classer", "Un dossier par question, des étiquettes pour l'état (retenue, à vérifier)"], ["Bibliographie", "Clic droit sur les références, puis « Créer une bibliographie » : style, format, copier"], ["Sans Zotero", "Tableur : auteur, année, titre, lien, note sur 12"]], "erreurs": ["Importer sans vérifier : des champs manquent souvent.", "Mélanger plusieurs styles de citation.", "Ne pas classer : on retrouve mal ses sources le jour de la rédaction."]}}, "EX11": {"id": "EX11", "titre": "Évaluer cinq sources", "mode": "Binôme", "duree": 25, "chap": "Carnet · chapitre 4", "situation": ["Sujet : l'authentification forte en entreprise. Cinq sources (fictives) :", "S1 — Article de revue à comité de lecture, 2024, méthode décrite, 3 organisations, limites discutées.", "S2 — Brochure commerciale d'un éditeur, 2025, chiffres sans méthode.", "S3 — Rapport d'une agence publique, 2023, mesures sur 120 organisations, méthode publiée.", "S4 — Billet de blog anonyme, 2022, « 100 % fiable » sans source.", "S5 — Article de presse généraliste, 2025, cite uniquement S2."], "taches": ["Notez chaque source de 0 à 2 sur 6 critères : Qui ? Quand ? Pourquoi ? Sur quoi (preuves) ? Recoupé ? Reproductible ? (maximum 12).", "Seuils : 9 et plus fiable ; 5 à 8 à recouper ; 4 et moins à écarter ou à citer avec prudence.", "Classez les sources.", "Que gardez-vous pour un état de l'art ?", "Pourquoi S5 n'ajoute-t-elle rien à S2 ?"], "livrable": "Un tableau de notation et la liste des sources retenues.", "corr": {"methode": ["Qui : auteur identifié et compétent ? Quand : récent pour le sujet ? Pourquoi : informer ou vendre ?", "Sur quoi : données et méthode visibles ? Recoupé : d'autres sources concordent ? Reproductible : méthode refaisable ?", "Additionner puis appliquer les seuils."], "cols": ["Source", "Q / Q / P / S / R / R", "Total", "Décision"], "widths": [0.7, 2.4, 0.9, 4.2], "rows": [["S1", "2 / 2 / 2 / 2 / 1 / 2", "11", "Fiable : retenue"], ["S3", "2 / 1 / 2 / 2 / 1 / 2", "10", "Fiable : retenue"], ["S5", "1 / 2 / 1 / 0 / 0 / 0", "4", "À écarter : source unique, reprend S2"], ["S2", "1 / 2 / 0 / 0 / 0 / 0", "3", "Citer comme position de l'éditeur seulement"], ["S4", "0 / 1 / 0 / 0 / 0 / 0", "1", "Écartée"]], "erreurs": ["Croire qu'un chiffre cité plusieurs fois est vrai : S5 dépend de S2 (source circulaire).", "Rejeter une brochure commerciale : on peut la citer comme position de l'acteur.", "Ne retenir que les sources qui confirment son idée (biais de confirmation)."]}}, "F4": {"id": "F4", "titre": "Flash · Fiable, à recouper ou prudence ?", "mode": "Individuel", "duree": 5, "chap": "Carnet · chapitre 4", "situation": ["Classez chaque source : fiable, à recouper, ou prudence.", "1. Thèse de doctorat en ligne d'une université, 2023.", "2. Livre blanc d'un éditeur de logiciels.", "3. Réponse d'un forum technique, validée par 200 votes.", "4. Rapport annuel d'une agence publique de cybersécurité."], "taches": ["Classez les quatre sources.", "Donnez une raison pour chacune."], "livrable": "", "corr": {"methode": ["Qui, pourquoi, méthode, date.", "Des votes ne sont pas des preuves."], "rows": [["1. Thèse", "Fiable, sous réserve : relue par un jury ; vérifier la date et les publications associées"], ["2. Livre blanc", "Prudence : position de l'éditeur, à citer comme telle"], ["3. Forum", "À recouper : bonne piste, pas une preuve (les votes mesurent la popularité)"], ["4. Rapport d'agence", "Fiable : vérifier la date et la méthode"]], "erreurs": ["Rejeter toute source commerciale.", "Faire confiance au nombre de votes."]}}, "EX12": {"id": "EX12", "titre": "Évaluer vos propres sources", "mode": "Individuel, ordinateur", "duree": 40, "chap": "Carnet · chapitre 4", "situation": ["Reprenez les résultats de vos recherches (EX8, EX9) dans Zotero.", "Grille en six questions, 0 à 2 points chacune : Qui ? Quand ? Pourquoi ? Sur quoi ? Recoupé ? Reproductible ? (maximum 12)."], "taches": ["Choisissez 5 sources de votre question.", "Notez-les avec la grille.", "Classez-les et gardez-en 3 au moins.", "Justifiez en une phrase chaque décision.", "Dans Zotero, ajoutez l'étiquette « retenue » ou « écartée »."], "livrable": "La grille de 5 sources remplie et 3 sources retenues dans Zotero.", "corr": {"methode": ["Noter chaque critère sans regarder le total.", "Appliquer les seuils : 9 et plus, 5 à 8, 4 et moins.", "Justifier : une phrase, un fait."], "cols": ["Cas (fictif)", "Notation et décision"], "widths": [3.0, 5.8], "rows": [["Rapport d'agence, 2023, méthode publiée", "2 / 1 / 2 / 2 / 1 / 2 = 10 : fiable, retenue"], ["Brochure d'éditeur, 2025, sans méthode", "1 / 2 / 0 / 0 / 0 / 0 = 3 : citer comme position de l'éditeur"], ["Article de revue relue, 2021, 3 organisations", "2 / 1 / 2 / 2 / 1 / 2 = 10 : retenue ; date à discuter selon le sujet"], ["Page de presse reprenant la brochure", "1 / 2 / 1 / 0 / 0 / 0 = 4 : écartée (source circulaire)"]], "erreurs": ["Noter « Recoupé » sans avoir cherché une autre source indépendante.", "Retenir cinq sources du même éditeur : elles ne se recoupent pas.", "Écarter sans justifier : le jury demandera pourquoi."]}}, "EX13": {"id": "EX13", "titre": "Remonter à la source d'un chiffre", "mode": "Binôme, ordinateur", "duree": 25, "chap": "Carnet · chapitre 4", "situation": ["Un article de presse (fictif) écrit : « 60 % des PME victimes d'une cyberattaque disparaissent dans les six mois. »", "Ce chiffre est souvent répété ; sa source n'est pas indiquée dans l'article. À vérifier par vos soins."], "taches": ["Cherchez l'origine de ce chiffre (guillemets, moteur de recherche).", "Notez le chemin : article, puis article, puis source d'origine.", "La source d'origine existe-t-elle ? Que mesure-t-elle exactement ?", "Que répondez-vous à la directrice qui veut citer ce chiffre ?"], "livrable": "Le chemin de vos recherches et votre phrase de réponse.", "corr": {"methode": ["Chaque article cite un autre article : remonter jusqu'au document primaire.", "Lire ce que la source mesure, sur qui, quand.", "À défaut de source primaire : ne pas citer comme un fait."], "cols": ["Situation trouvée", "Que faire ?"], "widths": [3.2, 5.6], "rows": [["Source d'origine trouvée et claire", "Citer la source d'origine, avec ce qu'elle mesure vraiment"], ["Source d'origine trouvée mais différente de l'affirmation", "Corriger la formulation : citer ce qui est réellement mesuré"], ["Aucune source primaire trouvée", "Écrire « chiffre fréquemment cité, sans source d'origine vérifiable » ou l'écarter"], ["Phrase de réponse à la directrice", "« Je n'ai pas pu retrouver l'étude d'origine : je propose de citer le chiffre comme non sourcé, ou de ne pas l'utiliser. »"]], "erreurs": ["S'arrêter au deuxième article qui répète le chiffre.", "Citer le chiffre parce qu'il est « connu ».", "Conclure qu'il est faux sans preuve : l'absence de source n'est pas une preuve du contraire."]}}, "F5": {"id": "F5", "titre": "Exit ticket · fin du jour 1", "mode": "Individuel", "duree": 10, "chap": "Carnet · tous chapitres", "situation": ["Dernier point de la journée : quatre phrases dans votre carnet."], "taches": ["Ma question de décision est : …", "Une source que j'ai écartée et pourquoi : …", "Ce que je ne sais pas encore : …", "Mon premier pas demain matin : …"], "livrable": ""}, "EX14": {"id": "EX14", "titre": "Lire un article scientifique en 10 minutes", "mode": "Individuel", "duree": 20, "chap": "Carnet · chapitre 5", "situation": ["Extrait d'un article (entièrement fictif) : « Authentification sans mot de passe et compromissions de comptes : étude sur 40 organisations », 2024.", "Méthode : 40 organisations volontaires ; comparaison des comptes compromis avant et après adoption, sur 12 mois ; pas de groupe témoin.", "Résultat : −42 % de comptes compromis après adoption.", "Limites signalées : organisations déjà sensibilisées ; un seul secteur (services) ; étude financée par un éditeur de solutions d'authentification."], "taches": ["Quelle est la question de l'article ?", "Quelle est la méthode ?", "Quel est le résultat principal, avec son chiffre ?", "Citez trois limites.", "Pouvez-vous écrire « l'authentification sans mot de passe réduit les compromissions de 42 % » ? Reformulez honnêtement."], "livrable": "Une fiche de lecture de 5 lignes.", "corr": {"methode": ["Lire dans l'ordre : résumé, conclusion, méthode, limites.", "Séparer le résultat (ce qui est mesuré) de l'interprétation.", "Toujours regarder qui finance."], "cols": ["Question", "Réponse"], "widths": [2.2, 6.6], "rows": [["Question", "L'authentification sans mot de passe réduit-elle les compromissions de comptes ?"], ["Méthode", "40 organisations volontaires, avant / après sur 12 mois, sans groupe témoin"], ["Résultat", "−42 % de comptes compromis après adoption"], ["Limites", "Volontaires déjà sensibilisées ; secteur unique ; absence de groupe témoin ; financement par un éditeur (possible conflit d'intérêts)"], ["Formulation honnête", "« Dans une étude de 40 organisations volontaires (2024, fictive), les compromissions ont baissé de 42 % après adoption, sans groupe témoin. »"]], "erreurs": ["Généraliser un résultat à toutes les organisations.", "Ignorer le financement et la présence ou non d'un groupe témoin.", "Citer le résumé sans lire la méthode."]}}, "EX15": {"id": "EX15", "titre": "Détecter une référence inventée", "mode": "Binôme", "duree": 15, "chap": "Carnet · chapitre 5", "situation": ["Une IA générative a produit quatre références (toutes fictives) pour votre état de l'art :", "1. Martin, L. et Dupont, C. (2023). Passwordless authentication at scale. Journal of Applied Cyber Futures, 12(3), 45-67. doi:10.9999/jacf.2023.0045", "2. Institut fictif de cybersécurité (2025). Le guide absolu de l'authentification. 412 pages.", "3. Nguyen, T. (2022). Zero trust and the end of passwords. Proceedings of the International Conference on Security Everywhere, p. 1-300.", "4. Rossi, M., Lopez, A., Chen, W. et al. (2021). A complete survey of every authentication method. Computing Reviews of Everything, 99(1), 1-12."], "taches": ["Quels indices doivent vous alerter dans chaque référence ?", "Quelle vérification faites-vous pour chacune (titre exact, revue, adresse DOI, auteurs) ?", "Que faites-vous d'une référence introuvable ?", "Quelle règle appliquez-vous avant de citer une source donnée par une IA ?"], "livrable": "Une liste d'indices et la règle de vérification.", "corr": {"methode": ["Chercher le titre exact entre guillemets.", "Ouvrir l'adresse DOI.", "Vérifier que la revue ou la conférence existe.", "Vérifier les auteurs."], "cols": ["Référence", "Indices et verdict"], "widths": [1.6, 7.2], "rows": [["1", "DOI qui ne s'ouvre pas (préfixe inventé) ; revue au nom trop générique : à ne pas citer"], ["2", "Titre « guide absolu » ; organisme introuvable ; nombre de pages rond : à ne pas citer"], ["3", "Conférence au nom vague ; pages 1 à 300 pour un seul article : incohérent"], ["4", "« A complete survey of every… » : titre trop parfait ; pages 1-12 pour un survey complet ; revue introuvable"], ["Règle", "Aucune référence donnée par une IA n'est citée avant d'avoir été ouverte et lue dans la source d'origine"]], "erreurs": ["Demander à la même IA de confirmer : elle peut confirmer une invention.", "Vérifier seulement l'orthographe des noms.", "Garder « au cas où » une référence introuvable."]}}, "F6": {"id": "F6", "titre": "Flash · Quel biais ?", "mode": "Individuel", "duree": 5, "chap": "Carnet · chapitre 5", "situation": ["Nommez le biais dans chaque situation (confirmation, survivant, publication, financement).", "1. Vous ne gardez que les articles qui disent que votre solution préférée est la meilleure.", "2. Seules les entreprises qui ont réussi publient leur retour d'expérience.", "3. Les études sans résultat marquant ne sont jamais publiées.", "4. L'étude est financée par le fabricant du produit testé."], "taches": ["Nommez le biais de chaque situation.", "Pour chacun, une parade."], "livrable": "", "corr": {"methode": ["Chercher aussi ce qui contredit.", "Regarder qui publie et qui finance."], "rows": [["1", "Biais de confirmation : chercher activement des sources qui contredisent"], ["2", "Biais du survivant : chercher aussi les échecs"], ["3", "Biais de publication : chercher les revues systématiques et les rapports ouverts"], ["4", "Biais de financement : lire les déclarations d'intérêts, rechercher une étude indépendante"]], "erreurs": ["Croire qu'une source financée est forcément fausse : elle demande seulement une vérification supplémentaire."]}}, "EX16": {"id": "EX16", "titre": "Cartographier un argument avec Toulmin", "mode": "Équipes", "duree": 20, "chap": "Carnet · chapitre 6", "situation": ["La directrice demande : « Pourquoi activer la double authentification partout ? » Un collègue répond :", "« Il faut l'activer partout, parce que 80 % des compromissions viennent de mots de passe volés. Tout le monde le fait. Et ça coûte peu. »"], "taches": ["Placez chaque élément dans le modèle de Toulmin : affirmation, données, garantie, fondement, réfutation, qualificatif.", "Repérez ce qui manque.", "Repérez l'élément qui n'est pas un argument.", "Réécrivez l'argument complet."], "livrable": "Une carte de Toulmin complétée.", "corr": {"methode": ["Affirmation : ce que je veux faire admettre.", "Données : les faits sourcés.", "Garantie : le lien entre données et affirmation.", "Fondement, réfutation, qualificatif : ce qui rend l'argument solide et honnête."], "cols": ["Case", "Contenu"], "widths": [1.8, 7.0], "rows": [["Affirmation", "Activer la double authentification partout"], ["Données", "« 80 % des compromissions viennent de mots de passe volés » : chiffre non sourcé, à vérifier"], ["Garantie", "Si la plupart des compromissions viennent de mots de passe volés, un second facteur en bloque la plupart"], ["Fondement", "Manquant : la source du chiffre"], ["Réfutation", "Manquante : vol du second facteur (SMS détourné, fatigue d'authentification), coût d'assistance"], ["Qualificatif", "Manquant : « probablement, d'abord pour les comptes à privilèges »"], ["Pas un argument", "« Tout le monde le fait » : appel à la popularité"]], "erreurs": ["Prendre un chiffre non sourcé pour une donnée.", "Oublier la réfutation : l'argument paraît trop sûr de lui.", "Garder « tout le monde le fait »."], "modele": ["Affirmation : Activer la double authentification, d'abord pour les comptes à privilèges.", "Données : [chiffre sourcé à trouver] sur la part des compromissions liées à des mots de passe volés.", "Garantie : un second facteur bloque l'usage d'un mot de passe volé.", "Réfutation : vol du second facteur (SMS détourné, fatigue d'authentification) ; coût d'assistance.", "Qualificatif : probablement efficace, sous réserve de choisir un second facteur résistant."], "retenir": "Un argument complet : affirmation, données sourcées, garantie, réfutation honnête, qualificatif."}}, "EX17": {"id": "EX17", "titre": "Chasser les sophismes", "mode": "Équipes", "duree": 10, "chap": "Carnet · chapitre 6", "situation": ["Six phrases entendues en réunion :", "1. « Tous les concurrents sont passés au cloud, donc nous devons y passer. »", "2. « Ce consultant n'a jamais administré de serveur : ignorez son rapport. »", "3. « Si on retarde la migration d'un mois, nous serons piratés. »", "4. « Soit on interdit l'IA générative, soit on perd toutes nos données. »", "5. « Deux utilisateurs trouvent le VPN lent : il ne marche pas. »", "6. « Depuis la mise à jour de jeudi, les tickets ont augmenté : la mise à jour est la cause. »"], "taches": ["Nommez le sophisme de chaque phrase (popularité, attaque contre la personne, pente glissante, faux dilemme, généralisation hâtive, post hoc).", "Expliquez en une phrase pourquoi le raisonnement est fragile.", "Écrivez une contre-question.", "Reformulez la phrase 6 en hypothèse testable."], "livrable": "", "corr": {"methode": ["Repérer le saut entre les raisons et la conclusion.", "Poser la question qui comble le saut."], "cols": ["Phrase", "Sophisme et contre-question"], "widths": [0.8, 8.0], "rows": [["1", "Appel à la popularité : « Qu'est-ce qui convient à notre contexte, indépendamment des concurrents ? »"], ["2", "Attaque contre la personne : « Que dit le rapport, et ses données tiennent-elles ? »"], ["3", "Pente glissante : « Quelle preuve qu'un mois de retard mène à une attaque ? »"], ["4", "Faux dilemme : « Existe-t-il une option encadrée (usages autorisés, données exclues) ? »"], ["5", "Généralisation hâtive : « Combien d'utilisateurs ont mesuré, avec quelles valeurs ? »"], ["6", "Post hoc : hypothèse testable : « Si la mise à jour est la cause, les tickets doivent concerner les postes mis à jour »"]], "erreurs": ["Nommer le sophisme sans dire pourquoi il est fragile.", "Répondre par une attaque : la contre-question doit rester ouverte."]}}, "EX18": {"id": "EX18", "titre": "Lire un chiffre de fournisseur", "mode": "Binôme", "duree": 15, "chap": "Carnet · chapitre 6", "situation": ["Brochure d'un éditeur (fictive) : « Notre solution réduit les incidents de 99 %. Adoptée par 500 entreprises. Leader du marché. »"], "taches": ["Écrivez cinq questions à poser sur le « 99 % » (par rapport à quoi, mesuré comment, sur quel échantillon, par qui, sur quelle durée).", "Repérez les deux arguments faibles de la brochure.", "Écrivez la phrase que vous mettriez dans votre état de l'art."], "livrable": "Cinq questions et la phrase d'état de l'art.", "corr": {"methode": ["Un pourcentage sans base n'est pas un fait.", "Chercher la méthode derrière le chiffre."], "cols": ["Question", "Réponse attendue"], "widths": [2.6, 6.2], "rows": [["Par rapport à quoi ?", "Quelle valeur de départ ? 99 % de 10 incidents ou de 10 000 ?"], ["Mesuré comment ?", "Définition d'un « incident », méthode de comptage"], ["Sur quel échantillon ?", "Combien de clients, lesquels, choisis par qui ?"], ["Par qui ?", "L'éditeur lui-même ou un tiers indépendant ?"], ["Sur quelle durée ?", "Un mois ou trois ans ?"], ["Arguments faibles", "« 500 entreprises » (popularité), « leader du marché » (autorité sans preuve)"], ["Phrase d'état de l'art", "« Selon la brochure de l'éditeur (2025), la solution réduirait les incidents de 99 % ; la méthode n'est pas publiée, ce chiffre est une position commerciale. »"]], "erreurs": ["Reprendre le chiffre sans le qualifier.", "Rejeter la source : on peut la citer comme position de l'éditeur."]}}, "EX19": {"id": "EX19", "titre": "Construire l'argument de votre équipe", "mode": "Équipes", "duree": 30, "chap": "Carnet · chapitre 6", "situation": ["Votre équipe a une question (EX1) et des sources notées (EX12).", "Écrivez votre premier argument avec le modèle de Toulmin."], "taches": ["Écrivez l'affirmation provisoire (votre recommandation).", "Choisissez deux données, chacune avec sa source.", "Écrivez la garantie et le fondement.", "Cherchez la réfutation : quand l'argument ne tient pas ?", "Choisissez un qualificatif honnête."], "livrable": "Votre fiche de Toulmin dans le carnet.", "corr": {"methode": ["Les données portent une référence.", "La garantie explique le lien.", "La réfutation est cherchée, pas subie.", "Le qualificatif dit la portée."], "cols": ["Case", "Exemple (sauvegarde de TransLor, fictif)"], "widths": [1.8, 7.0], "rows": [["Affirmation", "TransLor devrait ajouter une copie hors site de ses sauvegardes"], ["Données", "Disque unique de 3 ans ; restauration de 9 h lors du test de juin (interne)"], ["Garantie", "Une copie hors site permet de restaurer même si le local est touché, et réduit le temps d'arrêt"], ["Fondement", "Règle 3-2-1 des bonnes pratiques de sauvegarde (à sourcer : guide d'organisme public)"], ["Réfutation", "Sauf si les données sont peu critiques, ou si le débit empêche de restaurer vite"], ["Qualificatif", "Probablement, pour les données d'exploitation ; sous réserve de tester la restauration depuis le cloud"]], "erreurs": ["Une donnée sans référence.", "Une garantie qui répète l'affirmation.", "Pas de réfutation : le jury en trouvera trois."]}}, "EX20": {"id": "EX20", "titre": "Avocat du diable : répondre aux objections", "mode": "Équipes croisées", "duree": 25, "chap": "Carnet · chapitre 6", "situation": ["Chaque équipe présente son affirmation en une minute. Une autre équipe cherche deux objections. L'équipe répond par un fait, une concession ou une réserve."], "taches": ["Présentez votre affirmation en une minute.", "L'équipe voisine formule deux objections.", "Reformulez l'objection avant d'y répondre.", "Répondez par un fait, une concession ou une réserve.", "Notez ce que vous ajoutez à votre argument."], "livrable": "Deux objections et les réponses retenues.", "corr": {"methode": ["Écouter, reformuler, répondre, vérifier.", "Fait si on l'a ; concession si l'objection est juste ; réserve si on ne sait pas."], "cols": ["Type de réponse", "Exemple"], "widths": [2.2, 6.6], "rows": [["Un fait", "« Le test de juin donne 9 h de restauration ; le prestataire annonce 3 h. »"], ["Une concession", "« Vous avez raison : le coût mensuel s'ajoute. Je précise la conclusion : rentable si le risque dépasse 5 %. »"], ["Une réserve", "« Je n'ai pas le chiffre du débit : je le vérifie par un test avant la décision. »"]], "erreurs": ["Se justifier longuement.", "Nier une objection fondée.", "Répondre à côté : reformuler d'abord."]}}, "F7": {"id": "F7", "titre": "Exit ticket · fin du jour 2", "mode": "Individuel", "duree": 5, "chap": "Carnet · tous chapitres", "situation": ["Dernier point de la journée : quatre phrases dans votre carnet."], "taches": ["Mon argument principal est : …", "Ma réfutation la plus forte est : …", "Ce qu'il me manque pour conclure : …", "Mon premier pas demain matin : …"], "livrable": ""}, "EX21": {"id": "EX21", "titre": "Comparer trois solutions dans un tableur", "mode": "Groupe de 3, tableur", "duree": 30, "chap": "Carnet · chapitre 7", "situation": ["TransLor hésite sur la sauvegarde. Trois solutions (scores fictifs de 1 à 5, 5 = meilleur) :", "Disque local seul : coût 5, sécurité 2, restauration 2, simplicité 5.", "Cloud seul : coût 3, sécurité 4, restauration 4, simplicité 4.", "Hybride (local et cloud) : coût 2, sécurité 5, restauration 5, simplicité 3.", "Pondérations de départ : coût 30 %, sécurité 30 %, restauration 25 %, simplicité 15 %."], "taches": ["Dans un tableur, saisissez les scores et les poids (ligne séparée).", "Calculez la note de chaque solution avec =SOMMEPROD.", "Test de sensibilité : coût 50 %, sécurité 20 %, restauration 20 %, simplicité 10 %. Le classement change-t-il ?", "Rédigez la conclusion en 3 phrases, avec un qualificatif et une réserve."], "livrable": "Votre tableur et la conclusion.", "corr": {"methode": ["Note = somme (score × poids).", "Refaire avec d'autres poids pour voir si le classement tient.", "Conclure avec une réserve : les scores sont à sourcer."], "cols": ["Solution", "Base (30/30/25/15)", "Coût 50 % (50/20/20/10)"], "widths": [1.8, 3.2, 3.4], "rows": [["Disque local", "1,5 + 0,6 + 0,5 + 0,75 = 3,35", "2,5 + 0,4 + 0,4 + 0,5 = 3,80"], ["Cloud", "0,9 + 1,2 + 1,0 + 0,6 = 3,70", "1,5 + 0,8 + 0,8 + 0,4 = 3,50"], ["Hybride", "0,6 + 1,5 + 1,25 + 0,45 = 3,80", "1,0 + 1,0 + 1,0 + 0,3 = 3,30"], ["Classement", "Hybride > Cloud > Local", "Local > Cloud > Hybride : le classement s'inverse"], ["Formule", "=SOMMEPROD(B2:E2;$B$7:$E$7), poids dans des cellules séparées", ""]], "erreurs": ["Présenter un classement sans test de sensibilité : il peut s'inverser.", "Oublier que les scores sont des données à sourcer.", "Conclure sans réserve."], "modele": "« Avec les pondérations de départ, la solution hybride paraît la plus adaptée (3,80 contre 3,70 et 3,35), mais l'écart avec le cloud est faible. Si le coût devient prioritaire (50 %), le classement s'inverse : disque local 3,80, cloud 3,50, hybride 3,30. Avant de décider, il faut sourcer les scores (coûts réels, tests de restauration) ; ces notes sont fictives. »", "retenir": "Un état de l'art honnête : critères explicites, test de sensibilité, réserve, sources à vérifier."}}, "EX22": {"id": "EX22", "titre": "Votre matrice de comparaison", "mode": "Équipes, tableur", "duree": 45, "chap": "Carnet · chapitre 7", "situation": ["Votre équipe construit sa propre matrice : trois solutions, quatre critères (EX1), des scores sourcés."], "taches": ["Choisissez trois solutions à comparer.", "Justifiez les poids par les priorités de la directrice.", "Remplissez les scores en citant la source (référence Zotero) pour chacun.", "Calculez avec =SOMMEPROD et classez.", "Faites un test de sensibilité sur le critère le plus discutable.", "Écrivez une conclusion de 3 phrases avec qualificatif et réserve."], "livrable": "Votre matrice avec sources, le test de sensibilité et la conclusion.", "corr": {"methode": ["Chaque score a une source ou est signalé « estimation ».", "Poids justifiés.", "Test de sensibilité sur le point faible."], "cols": ["Critère de qualité", "Ce qui vaut le maximum"], "widths": [2.6, 6.2], "rows": [["Critères", "Comparables, mesurables, utiles à la décision"], ["Poids", "Justifiés par un besoin, somme égale à 100 %"], ["Scores", "Sourcés ; les estimations sont signalées"], ["Sensibilité", "Au moins un autre jeu de poids testé, résultat commenté"], ["Conclusion", "Recommandation avec qualificatif et réserve"]], "erreurs": ["Des scores sans source.", "Des critères qui se recouvrent (double comptage).", "Un classement présenté comme une vérité."]}}, "EX23": {"id": "EX23", "titre": "Plan de l'état de l'art et chapô", "mode": "Équipes", "duree": 20, "chap": "Carnet · chapitre 7", "situation": ["Votre état de l'art tient en deux pages. Avant d'écrire, il faut un plan et un résumé de trois lignes (chapô)."], "taches": ["Écrivez le plan : chaque partie en une ligne.", "Répartissez la longueur (en pourcentage de page).", "Écrivez le chapô : question, méthode, conclusion.", "Relisez : le lecteur a-t-il la réponse dans le chapô ?"], "livrable": "Le plan et le chapô de votre état de l'art.", "corr": {"methode": ["Le plan suit la démarche.", "Le chapô donne la conclusion d'abord."], "cols": ["Partie", "Contenu", "Longueur"], "widths": [2.6, 5.0, 1.2], "rows": [["1. Question", "Contexte et décision à éclairer", "10 %"], ["2. Méthode de recherche", "Requêtes, bases, période, sources retenues et écartées", "15 %"], ["3. Panorama", "Les solutions, chacune avec ses sources", "25 %"], ["4. Comparaison", "Matrice, test de sensibilité", "25 %"], ["5. Discussion et limites", "Réfutations, ce qu'on ne sait pas", "15 %"], ["6. Conclusion", "Recommandation avec qualificatif et réserve", "10 %"], ["Références", "Hors pages", ""]], "erreurs": ["Un panorama sans comparaison : on liste sans conclure.", "Une méthode absente : le lecteur ne peut pas refaire la recherche.", "Un chapô qui annonce le plan au lieu de la conclusion."], "modele": "Chapô (fictif) : « Pour décider si TransLor doit ajouter une copie hors site à ses sauvegardes, nous avons comparé trois solutions à partir de neuf sources évaluées. L'option hybride est la plus adaptée sous les pondérations de départ, mais le classement s'inverse si le coût devient prioritaire. Recommandation : tester la restauration depuis le cloud avant de décider. »", "retenir": "Un chapô donne la réponse : question, méthode, conclusion et réserve."}}, "EX24": {"id": "EX24", "titre": "Rédiger l'état de l'art (2 pages)", "mode": "Équipes, document partagé", "duree": 75, "chap": "Carnet · chapitre 7", "situation": ["Rédigez l'état de l'art de votre équipe en deux pages, avec le plan (EX23), la matrice (EX22) et les sources notées (EX12).", "Chaque affirmation de fait porte une référence ; la bibliographie vient de Zotero."], "taches": ["Répartissez les parties dans l'équipe.", "Rédigez en pyramide inversée : conclusion, puis preuves.", "Citez au moins 6 sources dans le texte.", "Générez la bibliographie avec Zotero.", "Relisez avec la liste de vérification (question, méthode, sources, comparaison, réserve)."], "livrable": "L'état de l'art de 2 pages dans un document partagé (lien) avec sa bibliographie.", "corr": {"methode": ["Plan d'abord, puis rédaction par partie.", "Une affirmation de fait = une référence.", "Relire avec la grille de notation."], "cols": ["Critère", "Points", "Ce qui vaut le maximum"], "widths": [2.4, 0.9, 5.5], "rows": [["Question et contexte", "2", "Décision claire, critères explicites"], ["Méthode de recherche", "3", "Requêtes, bases, dates, sources écartées : la recherche peut être refaite"], ["Qualité des sources", "4", "Sources variées, notées, avec au moins 3 fiables"], ["Comparaison", "4", "Matrice, test de sensibilité, résultats commentés"], ["Argumentation", "4", "Toulmin, réfutation, qualificatif et réserve"], ["Clarté et références", "3", "Pyramide inversée, bibliographie complète (total 20)"]], "erreurs": ["Lister des sources sans comparer.", "Citer sans référence précise.", "Une conclusion sans réserve."], "modele_titre": "Exemple d'extrait (fictif) : méthode de recherche", "modele": "« Nous avons interrogé Google Scholar (requête : « sauvegarde hors site » OR « off-site backup », période 2021-2026) et les publications de deux organismes publics. Sur 60 résultats lus, 9 ont été retenus après évaluation avec une grille en six questions (note de 9 ou plus sur 12). Les brochures commerciales sont citées comme positions d'éditeurs. »", "retenir": "Une méthode de recherche qu'un lecteur peut refaire vaut des points : requêtes, bases, dates, critères."}}, "EX25": {"id": "EX25", "titre": "Relecture croisée avec la grille", "mode": "Équipes croisées", "duree": 20, "chap": "Carnet · chapitre 7", "situation": ["Échangez votre état de l'art avec une autre équipe. Relisez avec la grille de notation (EX24) pendant 10 minutes, puis donnez un feedback SBI."], "taches": ["Relisez le document de l'autre équipe avec la grille.", "Notez deux points forts et deux améliorations, chacun avec un fait.", "Formulez un feedback en SBI : situation, comportement, impact.", "Écoutez le feedback reçu sans vous justifier ; reformulez.", "Décidez deux corrections à faire."], "livrable": "Deux points forts, deux améliorations, deux corrections décidées.", "corr": {"methode": ["Faits, pas jugements.", "SBI : situation, comportement, impact.", "Recevoir : écouter, reformuler, décider."], "cols": ["Feedback faible", "Feedback SBI (exemple)"], "widths": [3.0, 5.8], "rows": [["« Votre méthode est floue. »", "« Dans la partie 2 (S), les requêtes ne sont pas données (B) : un lecteur ne peut pas refaire la recherche (I). »"], ["« Bien écrit. »", "« Dans la conclusion (S), vous donnez une réserve précise (B) : le lecteur sait jusqu'où va votre recommandation (I). »"]], "erreurs": ["Juger la personne au lieu de décrire le texte.", "Se justifier au lieu de noter la correction."]}}, "EX26": {"id": "EX26", "titre": "Préparer le pitch de 5 minutes", "mode": "Équipes", "duree": 20, "chap": "Carnet · chapitre 8", "situation": ["Vous défendez votre état de l'art en 5 minutes devant un jury composé de la directrice (non technique) et de ses collaborateurs. Puis 4 minutes de questions."], "taches": ["Écrivez le message clé en une phrase.", "Construisez le plan : accroche, problème, solution, preuve, appel à décision.", "Préparez une analogie et un chiffre.", "Répartissez la parole entre les membres.", "Préparez les réponses aux 3 objections les plus probables.", "Chronométrez-vous une fois."], "livrable": "Votre message clé, votre plan et les trois objections préparées.", "corr": {"methode": ["Un message clé : une phrase que la directrice peut répéter.", "Un chiffre, une analogie, une demande.", "S'entraîner à voix haute, chronomètre en main."], "cols": ["Étape", "Exemple (fictif)"], "widths": [2.0, 6.8], "rows": [["Message clé", "« Une copie hors site coûte 1 800 € par an et évite une perte attendue de 4 000 €. »"], ["Accroche", "« En juin, restaurer la sauvegarde a pris 9 heures. »"], ["Problème", "« Un seul disque de 3 ans porte toute notre sauvegarde. »"], ["Solution", "« Ajouter une copie hors site, avec un test de restauration. »"], ["Preuve", "« 9 h contre 3 h ; 10 % de risque annuel (estimation). »"], ["Appel", "« Validez 1 800 € par an avant la fin du mois. »"]], "erreurs": ["Tout dire : 5 minutes = un message.", "Lire ses notes.", "Oublier l'appel à décision."]}}, "EX27": {"id": "EX27", "titre": "Pitch et défense devant le jury", "mode": "Équipes, jury", "duree": 65, "chap": "Carnet · chapitre 8", "situation": ["Chaque équipe présente 5 minutes, puis répond aux questions du jury 4 minutes. Les autres équipes observent et notent avec la grille (sur 20)."], "taches": ["Présentez votre état de l'art (5 minutes chronométrées).", "Répondez aux questions : reformuler, répondre par un fait, une concession ou une réserve.", "Observateurs : notez avec la grille et écrivez un feedback SBI.", "Après chaque équipe : une minute de feedback du jury."], "livrable": "La grille de notation de chaque équipe et un feedback SBI.", "corr": {"methode": ["Jury : un barème, des questions préparées, un feedback SBI.", "Équipe : message clé, preuve, réserve."], "cols": ["Critère", "Points", "Ce qui vaut le maximum"], "widths": [2.4, 0.9, 5.5], "rows": [["Message clé", "3", "Une phrase claire, répétée à la fin"], ["Structure", "3", "Accroche, problème, solution, preuve, appel enchaînés"], ["Clarté et vulgarisation", "3", "Aucun jargon non expliqué ; une analogie"], ["Preuves et sources", "4", "Chiffres sourcés, sources citées oralement"], ["Réponse aux questions", "4", "Reformule, répond par un fait, une concession ou une réserve"], ["Voix et posture", "3", "Débit calme, regard, pas de lecture (total 20)"]], "erreurs": ["Dépasser le temps.", "Répondre sans reformuler la question.", "Défendre sa conclusion sans réserve."], "modele_titre": "Questions types du jury", "modele": ["Pourquoi avoir retenu ces trois solutions et pas d'autres ?", "Comment avez-vous choisi les poids de vos critères ?", "Que se passe-t-il si votre chiffre principal est faux ?", "Quelle source est la plus fragile de votre état de l'art ?", "Quelle est votre réserve principale ?", "Que feriez-vous avec un mois de plus ?"], "retenir": "Défendre, c'est dire ce que l'on sait, ce que l'on ne sait pas, et comment on le vérifiera."}}, "EX28": {"id": "EX28", "titre": "Fiche : une vulnérabilité clé de mon organisation", "mode": "Individuel", "duree": 25, "chap": "Carnet · chapitre 9", "situation": ["Projet tutoré : dans l'organisation où vous êtes en apprentissage, repérez une vulnérabilité clé (pas seulement technique) : dépendance à une personne, information perdue, décision sans preuve, outil mal maîtrisé, message mal compris."], "taches": ["Décrivez la vulnérabilité : qui, quoi, quand, impact.", "Donnez une preuve : donnée, observation ou source.", "Construisez l'argument en Toulmin condensé : affirmation, données, garantie, réfutation.", "Rédigez une recommandation avec un qualificatif et une réserve.", "Dites comment vous la vérifierez avec votre tuteur."], "livrable": "Une fiche d'une page, à rendre au tuteur.", "corr": {"methode": ["Un fait observable, pas un jugement.", "Une preuve, même simple.", "Une recommandation datée et vérifiable."], "cols": ["Case", "Exemple (TransLor, fictif)"], "widths": [2.0, 6.8], "rows": [["Vulnérabilité", "Une seule personne (l'administrateur) sait restaurer le logiciel de tournées"], ["Qui, quoi, quand, impact", "Administrateur ; restauration ; en cas d'absence ; 60 conducteurs bloqués"], ["Preuve", "Test de juin : restauration faite par une seule personne, 9 h ; aucune procédure écrite"], ["Argument", "Affirmation : écrire la procédure et former un suppléant. Garantie : une procédure testée réduit la dépendance."], ["Recommandation", "Probablement : procédure écrite et test par le suppléant sous 60 jours ; réserve : charge de travail à confirmer"], ["Vérification", "Test chronométré avec le suppléant ; point avec le tuteur à J+60"]], "erreurs": ["Décrire un problème sans preuve.", "Une vulnérabilité trop large (« la cybersécurité »).", "Aucune manière de vérifier la recommandation."]}}, "EX29": {"id": "EX29", "titre": "Entraînement : questions de type examen", "mode": "Individuel", "duree": 20, "chap": "Carnet · chapitre 10", "situation": ["Format d'examen écrit (inventé : à adapter à votre format réel). Cinq questions courtes."], "taches": ["Q1. Complétez la carte de Toulmin de : « Il faut passer au cloud : tous nos concurrents l'ont fait. »", "Q2. Notez la source « blog anonyme, 2022, chiffres sans source » avec la grille en six questions.", "Q3. Quel sophisme dans « Soit on migre ce mois-ci, soit on perd nos clients » ?", "Q4. Écrivez une requête pour chercher des études sur la sauvegarde hors site, en français et en anglais.", "Q5. Réécrivez cette conclusion avec un qualificatif et une réserve : « Les passkeys sont meilleurs que les mots de passe. »"], "livrable": "Vos réponses, comparées à la correction.", "corr": {"methode": ["Répondre à la question posée, avec la méthode du cours.", "Citer un critère ou un terme précis."], "cols": ["Question", "Réponse attendue"], "widths": [1.0, 7.8], "rows": [["Q1", "Affirmation : passer au cloud. Données : « tous nos concurrents l'ont fait » (popularité, pas une donnée). Garantie manquante. Réfutation et qualificatif manquants."], ["Q2", "Qui 0, Quand 1, Pourquoi 0 ou 1, Sur quoi 0, Recoupé 0, Reproductible 0 : total 1 à 2 sur 12 : écarter"], ["Q3", "Faux dilemme : d'autres options existent (migration progressive, test sur un service)"], ["Q4", "« sauvegarde hors site » OR « off-site backup » OR « offsite backup », avec le filtre de dates"], ["Q5", "« Les passkeys sont probablement plus sûrs que les mots de passe pour l'hameçonnage ; réserve : compatibilité et coût de déploiement à vérifier. »"]], "erreurs": ["Répondre hors sujet : relire la consigne.", "Oublier la réserve dans une conclusion.", "Écrire une requête sans synonymes."]}}, "EX2": {"id": "EX2", "titre": "Diagnostiquer son style de communication", "mode": "Individuel", "duree": 10, "chap": "Carnet · chapitre 2", "situation": ["Notez chaque affirmation de 1 (pas du tout d'accord) à 4 (tout à fait d'accord).", "A. Direct / Nuancé", "1. Je dis franchement ce que je pense, même si cela peut déplaire.", "2. En réunion, je donne mon avis en premier plutôt que d'attendre.", "3. Je préfère une réponse courte et claire à un long développement.", "4. Quand je ne suis pas d'accord, je le dis tout de suite.", "B. Tâche / Relation", "5. Avant de parler d'un problème, je prends des nouvelles de la personne.", "6. Je repère vite l'ambiance et l'état d'esprit d'une équipe.", "7. Je préfère régler un désaccord à l'oral plutôt que par document.", "8. J'explique le contexte, pas seulement la consigne."], "taches": ["Additionnez les points A (affirmations 1 à 4) puis B (5 à 8).", "Placez-vous sur la grille : A de 11 à 16 = Direct, de 4 à 10 = Nuancé ; B de 11 à 16 = Relation, de 4 à 10 = Tâche. Le croisement donne votre profil.", "Lisez votre profil (force, risque, conseil) sur la correction.", "Comparez avec votre voisin : sur quelle situation vos styles se heurteraient-ils ?", "Appliquez : à quel personnage de TransLor (Marc, Paul, Sonia, la directrice) ressemblez-vous le plus ?"], "livrable": "Votre profil et un point d'attention, à noter dans le carnet (chapitre 1).", "corr": {"methode": ["Calculer A (4 à 16) et B (4 à 16).", "Direct si A ≥ 11, sinon Nuancé ; Relation si B ≥ 11, sinon Tâche.", "Lire la ligne du profil : force, risque, conseil.", "Se rappeler : aucun profil n'est meilleur, le piège est de parler à tout le monde comme à soi."], "cols": ["Profil", "Force", "Risque en entreprise", "Conseil"], "widths": [1.4, 2, 2.6, 2.6], "rows": [["Décideur\nDirect + Tâche", "Clarté, rapidité", "Paraît brusque, oublie le contexte", "Ajouter une phrase de contexte"], ["Animateur\nDirect + Relation", "Énergie, lien", "Dilue le message dans l'ambiance", "Finir par une demande précise"], ["Analyste\nNuancé + Tâche", "Rigueur, précision", "Trop long, décision retardée", "Donner la conclusion d'abord"], ["Facilitateur\nNuancé + Relation", "Écoute, consensus", "Évite le désaccord nécessaire", "Oser dire non avec une alternative"]], "erreurs": ["Se noter selon l'image que l'on voudrait donner plutôt que selon ses réactions réelles.", "Croire que le test mesure la personnalité : c'est un modèle pédagogique simplifié, pas un outil de recrutement.", "Sur TransLor : Marc (Décideur) écrit court ; Paul (Facilitateur) peut lire ses messages comme brusques. Le problème est l'écart, pas le style."]}}, "F1": {"id": "F1", "titre": "Flash · Vrai ou faux sur la communication", "mode": "Solo puis voisin", "duree": 5, "chap": "Carnet · chapitre 2", "situation": ["1. 93 % du message passe par le non-verbal.", "2. Un silence peut être une réponse.", "3. Le récepteur décode toujours le message comme l'émetteur l'a encodé.", "4. Le feedback ferme la boucle de communication.", "5. Pour un désaccord chargé d'émotion, un e-mail est plus sûr qu'un appel."], "taches": ["Répondez Vrai ou Faux pour chaque affirmation.", "Justifiez en une phrase.", "Citez un exemple chez TransLor pour l'affirmation 3."], "livrable": "", "corr": {"methode": ["Séparer ce qui est établi de ce qui est un mythe.", "Penser à un exemple concret."], "rows": [["1", "Faux : les 7 % / 38 % / 55 % de Mehrabian portent sur des messages de sentiments incohérents en laboratoire, pas sur toute communication."], ["2", "Vrai : le silence est un signal (accord, désaccord, réflexion) à vérifier par une question."], ["3", "Faux : le décodage dépend du cadre de référence ; d'où le feedback."], ["4", "Vrai : sans retour, l'émetteur ignore ce qui a été compris."], ["5", "Faux : l'écrit supprime le ton et amplifie les malentendus ; on appelle d'abord, on confirme ensuite par écrit."]], "erreurs": ["Retenir « 93 % non-verbal » : chiffre souvent cité hors contexte."]}}, "EX3": {"id": "EX3", "titre": "Reformuler : écho, clarification, synthèse, reflet", "mode": "Binôme", "duree": 15, "chap": "Carnet · chapitre 2", "situation": ["Six phrases entendues chez TransLor. Pour chacune, écrivez une reformulation de 15 mots maximum et nommez son type.", "1. Marc : « Je n'en peux plus de ces tableaux Excel. »", "2. Léa : « La tablette plante dès que j'arrive à l'entrepôt. »", "3. La directrice : « Il me faut une solution pour le dernier kilomètre avant l'été, sans exploser le budget. »", "4. Sonia : « Les factures arrivent toujours en retard, je ne peux pas clôturer. »", "5. Paul : « Les conducteurs sont démotivés, on devrait tout revoir. »", "6. Léa : « Franchement, on ne nous écoute jamais. »"], "taches": ["Rappel des types : écho (répéter l'essentiel), clarification (préciser), synthèse (regrouper), reflet (nommer l'émotion).", "Écrivez votre reformulation pour chaque phrase.", "Nommez le type utilisé.", "Soulignez, dans vos reformulations, tout conseil ou jugement caché, et retirez-le.", "Choisissez la phrase la plus risquée et dites pourquoi."], "livrable": "Six reformulations, chacune avec son type.", "corr": {"methode": ["Repérer le fait et l'émotion dans la phrase.", "Choisir le type : écho, clarification, synthèse ou reflet.", "Redire avec ses mots, sans conseil ni jugement.", "Terminer par une invitation à confirmer ou à préciser."], "cols": ["Phrase", "Type conseillé", "Exemple de reformulation"], "widths": [0.8, 1.5, 4.6], "rows": [["1", "Reflet", "« Cette saisie manuelle vous épuise ? »"], ["2", "Écho + clarification", "« Elle plante à l'arrivée à l'entrepôt : à chaque fois ? »"], ["3", "Synthèse", "« Deux contraintes : avant l'été et budget maîtrisé. Laquelle prime si on doit choisir ? »"], ["4", "Reflet + clarification", "« Le retard bloque votre clôture. De qui dépendent ces factures ? »"], ["5", "Clarification", "« Qu'avez-vous observé qui vous fait dire qu'ils sont démotivés ? »"], ["6", "Reflet", "« Vous avez le sentiment de ne pas être entendue. Sur quel sujet récemment ? »"]], "erreurs": ["Répéter mot à mot : cela ressemble à un écho de perroquet et n'apporte rien.", "Glisser un conseil : « Vous devriez demander une tablette neuve ».", "Reformuler en changeant le sens : la phrase 5 est un jugement de Paul, pas un fait ; la clarification demande les faits."]}}, "EX4": {"id": "EX4", "titre": "Recueillir un besoin : l'entretien avec Marc", "mode": "Binôme (enquêteur / Marc)", "duree": 25, "chap": "Carnet · chapitre 2", "situation": ["Marc, gestionnaire d'exploitation, vous dit : « Je voudrais un export Excel des tournées du jour. »", "Vous êtes l'ingénieur chargé d'étudier la demande. Votre binôme joue Marc (sa fiche de rôle est sur l'application, à ne pas montrer à l'enquêteur).", "Vous avez 8 minutes. Ne proposez aucune solution avant d'avoir compris le besoin."], "taches": ["Préparez 6 questions en entonnoir : large, puis précis, puis de confirmation.", "Menez l'entretien (8 minutes).", "Reformulez le besoin réel en une phrase.", "Chiffrez le coût actuel : 45 min par jour et par gestionnaire, 225 jours, 15 gestionnaires, 32 € de l'heure.", "Faites valider par Marc le critère de réussite."], "livrable": "Besoin reformulé, coût annuel, critère de réussite.", "fiche_role": "FICHE DE MARC (secrète). Demande affichée : un export Excel des tournées. Besoin réel : savoir avant 7 h quelles tournées risquent un retard pour prévenir les clients. À dévoiler seulement si l'enquêteur pose des questions ouvertes : 20 tournées par jour, 12 % dépassent le créneau, il recopie les heures dans Excel 45 minutes par jour, 3 clients (60 % du CA) pénalisent les retards, budget maximal 2 k€, critère de réussite : une alerte au moins 30 minutes avant le créneau. Si on vous propose une solution trop vite, répondez « oui, peut-être ».", "corr": {"methode": ["Questions larges : « Racontez-moi une matinée type ». Puis précises : fréquence, durée, impact.", "Demander à quoi servira l'export (le besoin derrière la solution).", "Reformuler en une phrase besoin + critère.", "Chiffrer l'impact avant de proposer."], "rows": [["Besoin réel", "Voir avant 7 h les tournées à risque de retard, pour prévenir les clients à temps"], ["Fréquence du problème", "20 tournées × 12 % = 2,4 tournées en retard par jour ; 2,4 × 225 = 540 par an"], ["Coût actuel de la ressaisie", "0,75 h × 225 j × 32 € = 5 400 € par gestionnaire ; × 15 = 81 000 € par an"], ["Critère de réussite", "Alerte au moins 30 minutes avant le créneau, budget ≤ 2 k€"], ["Phrase de reformulation", "« Vous voulez être alerté 30 minutes avant un retard probable pour prévenir vos clients, sans ressaisie ; l'export n'est qu'un moyen. »"]], "erreurs": ["Proposer « on vous fait un export » dès la première minute : la solution précède le besoin.", "Enchaîner des questions fermées : on obtient oui ou non, pas le contexte.", "Oublier de chiffrer : sans 81 000 €, la demande ne passe pas l'arbitrage du budget."]}}, "EX5": {"id": "EX5", "titre": "Corriger trois e-mails : avant / après", "mode": "Binôme", "duree": 15, "chap": "Carnet · chapitre 2", "situation": ["Trois e-mails reçus chez TransLor. Lisez-les, puis corrigez-les.", "E1, envoyé à la directrice. Objet : « Question ». Texte : « Je pense qu'on pourrait faire autrement, mais je ne sais pas si c'est possible. Qu'en pensez-vous ? »", "E2, envoyé à Marc. Objet : « Re: Re: Re: Fwd: tournées ». Texte : trois sujets mélangés (planning de lundi, tablette de Léa, facture carburant), sans demande claire.", "E3 : « OK merci ! » envoyé en « Répondre à tous » à 40 personnes."], "taches": ["Pour chaque e-mail, trouvez trois défauts.", "Réécrivez l'objet de E1 et de E2 (8 mots maximum).", "Réécrivez le texte de E1 en 4 lignes, conclusion en premier.", "E2 : faut-il un seul e-mail ou trois ?", "Que répondez-vous à l'auteur de E3 ?"], "livrable": "Trois e-mails corrigés.", "corr": {"methode": ["Objet = sujet + action attendue.", "Un e-mail = un sujet.", "Conclusion d'abord, détails ensuite.", "Répondre à tous seulement si tous doivent le savoir."], "rows": [["E1 : défauts", "Objet vide ; idée vague (« autrement ») ; pas d'action ni d'échéance"], ["E1 : objet", "« Décision avant jeudi : changer l'ordre des tournées ? »"], ["E1 : corps", "« Je propose d'inverser les tournées 3 et 4 pour gagner 20 minutes. Votre accord est nécessaire avant jeudi 12 h. Contexte : deux retards cette semaine. Je vous détaille en annexe. »"], ["E2 : traitement", "Trois e-mails séparés, chacun avec son objet : « Planning lundi : validation », « Tablette Léa : panne », « Facture carburant : justificatif »"], ["E3 : conseil", "Ne pas répondre à tous ; pour remercier, utiliser une réaction ou répondre à l'expéditeur seul"]], "erreurs": ["Laisser un fil « Re: Re: Fwd » qui ne reflète plus le sujet.", "Mettre la demande à la fin d'un long paragraphe.", "Aucune échéance : la demande n'est jamais traitée."]}}, "F2": {"id": "F2", "titre": "Flash · Pyramide inversée : remettre le message dans l'ordre", "mode": "Binôme", "duree": 4, "chap": "Carnet · chapitre 2", "situation": ["Cinq phrases d'un e-mail à la directrice, mélangées :", "A. Contexte : lors du comité du 3 mars, deux options ont été discutées.", "B. Détails : option 1 coûte 40 k€, option 2 coûte 55 k€ mais réduit les retards.", "C. Je recommande l'option 2.", "D. Merci de confirmer avant jeudi 12 h.", "E. Cordialement."], "taches": ["Remettez les phrases dans l'ordre d'un message efficace.", "Justifiez en une phrase.", "Quelle phrase mettre dans l'objet ?"], "livrable": "", "corr": {"methode": ["Conclusion d'abord, action ensuite, contexte et détails après."], "rows": [["Ordre", "C, D, A, B, E"], ["Pourquoi", "La directrice lit d'abord la décision et l'échéance, puis choisit de lire le détail"], ["Objet", "« Option 2 recommandée : confirmation avant jeudi 12 h »"]], "erreurs": ["Raconter l'historique avant la conclusion."]}}, "F8": {"id": "F8", "titre": "Flash · Vulgariser trois phrases techniques", "mode": "Binôme", "duree": 6, "chap": "Carnet · chapitre 8", "situation": ["Traduisez pour la directrice (non technique), en une phrase, sans jargon :", "1. « Le TMS a une latence élevée aux heures de pointe. »", "2. « Nous allons segmenter le réseau en VLAN. »", "3. « Le RPO est de 4 heures. »"], "taches": ["Écrivez une phrase par traduction.", "Ajoutez une analogie pour la phrase 2.", "Testez sur votre voisin : a-t-il compris sans question ?"], "livrable": "", "corr": {"methode": ["Partir de l'enjeu de l'auditeur (retard, argent, risque).", "Remplacer le terme par ce qu'il change concrètement.", "Une analogie, pas trois."], "rows": [["1", "« Le logiciel de tournées répond lentement quand tout le monde s'y connecte vers 7 h. »"], ["2", "« Nous séparons le réseau en zones, comme des pièces avec des portes : un incident ne se propage plus partout. »"], ["3", "« Si une panne survient, nous pouvons perdre au maximum 4 heures de données. »"]], "erreurs": ["Remplacer un sigle par un autre sigle.", "Une analogie trop longue qui devient plus compliquée que le sujet."]}}, "F9": {"id": "F9", "titre": "Exit ticket · fin du cours", "mode": "Individuel", "duree": 5, "chap": "Carnet · tous chapitres", "situation": ["Sur une demi-page du carnet, en 5 minutes."], "taches": ["Ce que j'ai appris de plus utile.", "Ce que je fais différemment dès lundi.", "Ce qui manquait ou était de trop dans ce cours.", "Une note de 1 à 5 : utilité en entreprise."], "livrable": ""}, "AX2": {"id": "AX2", "titre": "Chiffrer le coût de la non-communication", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 1", "situation": ["TransLor : 120 salariés, 14 M€ de chiffre d'affaires, marge d'environ 280 k€ (2 %).", "Hypothèses pédagogiques (inventées) : chaque salarié perd en moyenne 1,5 h par semaine en précisions, reprises et messages inutiles ; 45 semaines travaillées ; coût horaire chargé moyen 32 €.", "Un plan de communication (une journée de formation par salarié, 7 h, plus 6 000 € de prestation) pourrait réduire cette perte de 40 %."], "taches": ["Calculez les heures perdues par an.", "Calculez le coût annuel.", "Exprimez-le en % du chiffre d'affaires puis en % de la marge.", "Calculez le gain annuel si la perte baisse de 40 %.", "Calculez le coût du plan, le ROI de la première année et le délai de retour en mois.", "Refaites le calcul avec une décote de 50 % sur le gain (prudence). Que décidez-vous ?"], "livrable": "Un tableau de calcul ligne par ligne et une recommandation en deux phrases.", "corr": {"methode": ["Heures = salariés × h/semaine × semaines.", "Coût = heures × coût horaire.", "Rapporter au CA (14 M€) et à la marge (280 k€).", "Gain = coût × 40 %. Coût du plan = 120 × 7 h × 32 € + 6 000 €.", "ROI = (gain − coût) / coût ; retour (mois) = coût / gain × 12."], "rows": [["Heures perdues par an", "120 × 1,5 × 45 = 8 100 h"], ["Coût annuel", "8 100 × 32 = 259 200 €"], ["En % du CA et de la marge", "259 200 / 14 000 000 = 1,85 % du CA ; 259 200 / 280 000 = 92,6 % de la marge"], ["Gain à −40 %", "259 200 × 0,40 = 103 680 €"], ["Coût du plan, ROI, retour", "120 × 7 × 32 = 26 880 ; + 6 000 = 32 880 € ; ROI = 70 800 / 32 880 = 215 % ; retour 32 880 / 103 680 × 12 = 3,8 mois"], ["Avec décote de 50 %", "Gain 51 840 € ; ROI = 18 960 / 32 880 = 57,7 % ; retour 7,6 mois → reste rentable : on lance le plan"]], "erreurs": ["Oublier le coût de présence des salariés en formation (26 880 €), qui est le plus gros poste du plan.", "Présenter 259 200 € comme un fait : ce sont des hypothèses inventées. Toujours annoncer les hypothèses et tester une version prudente.", "Confondre ROI (215 %) et délai de retour (3,8 mois)."]}}, "AX3": {"id": "AX3", "titre": "Analyser un échange raté entre exploitation et informatique", "mode": "Binôme", "duree": 10, "chap": "Carnet · chapitre 1", "situation": ["Messagerie interne de TransLor, entre Marc (gestionnaire d'exploitation) et l'administrateur système :", "Lundi 8 h 10, Marc : « Le TMS est lent, il faut régler ça vite. »", "Lundi 8 h 40, Admin : « OK, je regarde. »", "Jeudi 9 h 05, Marc : « Toujours rien ! Mes gars perdent un temps fou. »", "Jeudi 9 h 30, Admin : « J'ai ajouté de la mémoire au serveur, c'est fait. »", "Jeudi 9 h 45, Marc : « Mais c'est l'écran des tournées qui rame, vers 7 h, pas le serveur… »"], "taches": ["Pour chaque message, notez ce qui manque (quoi, où, quand, combien, pour quand).", "Nommez le type de bruit en cause (technique, sémantique, psychologique, organisationnel).", "Retrouvez le vrai problème tel que Marc le décrit.", "Quelle question de clarification l'administrateur aurait-il dû poser dès lundi ?", "Réécrivez le message initial de Marc en 4 lignes, conclusion d'abord."], "livrable": "Le message de Marc réécrit et la question de clarification de l'administrateur.", "corr": {"methode": ["Relire chaque message avec les 5 questions : quoi, où, quand, combien, pour quand.", "Repérer les mots flous (« lent », « vite », « je regarde »).", "Chercher quelle solution a été choisie avant le diagnostic.", "Réécrire : conclusion, impact, attendu, échéance."], "rows": [["Ce qui manque", "« lent » : quelle fonction, quand, combien de secondes ? « vite » : pour quand ? « je regarde » : aucun retour promis"], ["Bruit en cause", "Sémantique (mots flous), organisationnel (pas de ticket), psychologique (agacement croissant)"], ["Vrai problème", "L'écran Tournées ralentit autour de 7 h (pic de connexions) ; l'ajout de mémoire du serveur répondait à une autre question"], ["Question de clarification", "« Quelle fonction est lente, à quelle heure, et combien de temps cela dure-t-il ? Qu'est-ce qui serait acceptable ? »"], ["Cause racine de l'échec", "Solution choisie avant le diagnostic, sans critère de réussite partagé"]], "erreurs": ["Chercher un coupable (Marc trop vague ou l'admin trop passif) : les deux ont une part, le système n'imposait aucune précision.", "Proposer « plus de réunions » : il fallait un ticket avec impact et critère de réussite.", "Oublier de rappeler la date de retour : « je regarde » sans échéance équivaut à « je ne m'engage pas »."], "modele": "Objet : TMS – écran Tournées : 25 s de chargement entre 6 h 45 et 7 h 30\n\nMarc, à l'administrateur : « L'écran Tournées met environ 25 secondes à s'ouvrir entre 6 h 45 et 7 h 30, pour les 15 gestionnaires. Les départs sont retardés d'environ 10 minutes. J'attends moins de 5 secondes. Pouvez-vous me proposer un diagnostic d'ici jeudi ? Je suis disponible à 7 h pour reproduire le problème. »\n\n(Valeurs 25 s et 10 min inventées pour l'exemple.)", "retenir": "Un message utile contient : conclusion, impact chiffré, attendu mesurable, échéance."}}, "AX5": {"id": "AX5", "titre": "Triades d'écoute : parleur, écouteur, observateur", "mode": "Groupe de 3", "duree": 18, "chap": "Carnet · chapitre 2", "situation": ["Trois manches de 6 minutes : 3 min d'entretien, 2 min de retour, 1 min de changement de rôle. Chacun joue les trois rôles.", "Parleur : raconte une situation professionnelle réelle et non confidentielle (ou le cas de Léa : « la tablette plante et on ne m'écoute pas »).", "Écouteur : n'a le droit qu'aux reformulations et aux questions ouvertes. Aucun conseil, aucune histoire personnelle.", "Observateur : note les comportements sur la grille (chronomètre, silences, reformulations, questions, conseils)."], "taches": ["Parleur : exposez la situation en 1 minute, puis répondez.", "Écouteur : faites au moins 3 reformulations et 2 questions ouvertes.", "Observateur : remplissez la grille d'observation.", "Retour en 3 minutes : l'observateur parle d'abord, puis le parleur dit ce qui l'a aidé.", "Notez un geste d'écoute à conserver et un à abandonner."], "livrable": "La grille d'observation remplie pour chaque manche.", "corr": {"methode": ["L'observateur compte, ne juge pas.", "Le parleur dit ce qui l'a aidé avant tout commentaire.", "L'écouteur se corrige sur un seul point à la fois.", "Chacun note un engagement concret dans le carnet."], "cols": ["Critère observé", "Cible", "Comment le noter"], "widths": [2.5, 1.2, 4.3], "rows": [["Temps de parole de l'écouteur", "moins de 30 %", "Chronomètre : secondes de parole / 180"], ["Reformulations", "3 ou plus", "Un trait par reformulation réussie, sans conseil"], ["Questions ouvertes", "2 ou plus", "« Comment », « Qu'est-ce que », « Raconte-moi »"], ["Conseils ou jugements", "0", "Un trait par « tu devrais », « moi à ta place »"], ["Silence toléré", "au moins 3 s une fois", "L'écouteur laisse un blanc sans le combler"], ["Synthèse finale", "oui", "Résumé en une phrase validé par le parleur"]], "erreurs": ["Remplir les silences : le parleur n'a pas le temps de creuser.", "Raconter « moi aussi » : l'attention passe de l'autre à soi.", "Observateur qui intervient pendant l'entretien : il note, il ne parle pas."]}}, "AX7": {"id": "AX7", "titre": "Reconnaître les quatre comportements", "mode": "Binôme", "duree": 8, "chap": "Carnet · chapitre 3", "situation": ["Classez chaque phrase : passif, agressif, manipulateur ou assertif.", "1. « Bon, d'accord, je m'en occupe… (soupir) comme d'habitude. »", "2. « Encore un retard ! Vous ne servez à rien ! »", "3. « Je ne peux pas livrer demain, mais vendredi à 12 h. Qu'en pensez-vous ? »", "4. « Oh, ce n'est pas grave, ne vous inquiétez pas pour moi. » (alors qu'il y a un vrai problème)", "5. « Tout le monde pense que ton code est mauvais. »", "6. « Si tu m'appréciais, tu prendrais mon astreinte. »"], "taches": ["Classez les 6 phrases.", "Justifiez chaque classement par un indice (ton, généralisation, reproche, chantage…).", "Réécrivez les phrases 2 et 5 en version assertive.", "Identifiez votre comportement par défaut quand vous êtes sous pression.", "Citez une situation de TransLor où vous seriez tenté par l'un des trois comportements non assertifs."], "livrable": "Le tableau de classement et deux phrases réécrites.", "corr": {"methode": ["Chercher qui est respecté : moi, l'autre, ou les deux ?", "Repérer les mots absolus (« toujours », « jamais », « tout le monde »).", "L'assertif décrit un fait, exprime un besoin et propose.", "Réécrire sans jugement sur la personne."], "cols": ["Phrase", "Comportement", "Indice", "Version assertive"], "widths": [0.6, 1.4, 2.4, 3.6], "rows": [["1", "Manipulateur (passif-agressif)", "Accord de façade + reproche indirect", "« Je peux le faire cette semaine ; la prochaine fois, partageons-nous la charge. »"], ["2", "Agressif", "Jugement sur les personnes, généralisation", "« Ce colis est arrivé avec 2 h de retard. Je veux comprendre pourquoi. »"], ["3", "Assertif", "Fait, limite, alternative, question", "—"], ["4", "Passif", "Nie son besoin pour éviter le conflit", "« Si, c'est un souci : j'ai besoin de… »"], ["5", "Agressif / manipulateur", "Appel au « tout le monde », jugement", "« Dans cette revue, j'ai relevé trois fonctions sans test. Peux-tu en ajouter ? »"], ["6", "Manipulateur", "Chantage affectif", "« Peux-tu prendre mon astreinte ? Je te rends la pareille le mois prochain. »"]], "erreurs": ["Confondre assertif et poli : on peut être très poli et passif-agressif.", "Prendre « tout le monde pense » pour un fait : c'est une pression sociale.", "Croire que l'assertivité impose d'obtenir gain de cause : elle garantit d'être clair et respectueux, pas d'avoir raison."]}}, "AX8": {"id": "AX8", "titre": "Six situations : DESC, SBI ou « oui, si… » ?", "mode": "Groupe de 3", "duree": 20, "chap": "Carnet · chapitre 3", "situation": ["Pour chaque situation, choisissez la méthode (DESC : décrire, exprimer, spécifier, conséquences ; SBI : situation, comportement, impact ; « oui, si… ») et écrivez la phrase clé.", "1. Revue de code : un collègue a écrit « code illisible » sur votre demande de fusion.", "2. Un collègue livre en retard pour la 3e fois ; votre propre livraison est bloquée.", "3. La directrice demande une démo pour demain, alors que l'équipe est à 100 % de charge.", "4. Un client appelle, furieux : sa livraison est partie à la mauvaise adresse.", "5. Un collègue vous coupe la parole en réunion.", "6. Le prestataire du TMS livre la mise à jour avec 3 jours de retard."], "taches": ["Choisissez la méthode pour chaque situation.", "Écrivez la phrase clé (30 mots maximum).", "Vérifiez qu'elle contient un fait observable et pas un jugement.", "Choisissez la situation la plus délicate et dites quel canal (oral, écrit) convient.", "Jouez la situation 5 à deux, 1 minute."], "livrable": "Un tableau situation, méthode, phrase clé.", "corr": {"methode": ["Situation entre pairs sur un comportement : SBI ou DESC.", "Demande qui dépasse la capacité : « oui, si… » avec alternatives.", "Client en colère : écouter, reformuler, puis proposer.", "Relire : aucun adjectif sur la personne."], "cols": ["Situation", "Méthode", "Phrase clé"], "widths": [0.7, 1.3, 6.3], "rows": [["1", "SBI", "« Dans ma demande de fusion de ce matin, ton commentaire « illisible » ne m'indique pas quoi changer ; peux-tu citer les lignes concernées ? »"], ["2", "DESC", "« Trois livraisons ont dépassé la date. Je suis bloqué sur ma partie. Peux-tu me donner une date ferme ? Sinon, je préviens le chef de projet vendredi. »"], ["3", "Oui, si…", "« Oui pour une démo demain si nous retirons la fonction B ; sinon je propose jeudi pour la version complète. »"], ["4", "Écoute puis solution", "« Votre colis est parti à la mauvaise adresse, c'est inacceptable. Je confirme : adresse, heure. Je rappelle dans 30 minutes avec une solution. »"], ["5", "SBI immédiat", "« Je n'avais pas fini ma phrase. Je termine, puis je te laisse la parole. »"], ["6", "DESC écrit", "« La mise à jour devait arriver lundi et arrive jeudi, ce qui retarde nos tests. Nous attendons un planning révisé d'ici demain. »"]], "erreurs": ["Écrire « il est toujours en retard » : jugement, pas comportement.", "Dire non sans alternative à la directrice : la relation se tend et la décision se retarde.", "Régler par écrit une situation émotionnelle (4) : décrocher d'abord, confirmer par écrit ensuite."]}}, "AF2": {"id": "AF2", "titre": "Flash · Questions ouvertes, fermées ou biaisées ?", "mode": "Binôme", "duree": 5, "chap": "Carnet · chapitre 2", "situation": ["a. « Pourquoi n'avez-vous pas fait la saisie ? »", "b. « Peux-tu me décrire une tournée type ? »", "c. « Le retard vient-il du chargement ? »", "d. « Combien de temps cela prend-il ? »", "e. « Vous êtes d'accord, non ? »", "f. « Qu'est-ce qui serait un bon résultat pour toi ? »"], "taches": ["Classez chaque question : ouverte, fermée ou biaisée (suggestive ou accusatoire).", "Réécrivez a et e en questions neutres.", "Gardez les deux meilleures pour un entretien de recueil de besoin."], "livrable": "", "corr": {"methode": ["Ouverte : appelle un développement. Fermée : oui, non ou un chiffre.", "Biaisée : suggère la réponse ou contient un reproche."], "rows": [["a", "Ouverte mais accusatoire : « Qu'est-ce qui a empêché la saisie ? »"], ["b", "Ouverte : excellente pour démarrer"], ["c", "Fermée : utile pour vérifier une hypothèse"], ["d", "Fermée chiffrée : utile pour quantifier"], ["e", "Biaisée (suggestive) : « Qu'en pensez-vous ? »"], ["f", "Ouverte : fait émerger le critère de réussite"]], "erreurs": ["Abuser des « pourquoi », perçus comme un reproche.", "Rester sur des questions fermées : on confirme ses hypothèses au lieu de découvrir le besoin."]}}, "AF3": {"id": "AF3", "titre": "Flash · Fait observable ou jugement ?", "mode": "Solo puis voisin", "duree": 4, "chap": "Carnet · chapitre 3", "situation": ["1. « Tu es négligent. »", "2. « Hier, tu as livré sans scanner trois colis. »", "3. « Tu fais mal ton travail. »", "4. « En réunion de 9 h, tu as coupé la parole à Sonia deux fois. »", "5. « Tu te moques des délais. »"], "taches": ["Marquez F (fait observable) ou J (jugement).", "Transformez chaque jugement en fait observable (SBI : situation, comportement)."], "livrable": "", "corr": {"methode": ["Un fait se filme : on peut le voir ou le mesurer.", "Un jugement qualifie la personne."], "rows": [["1", "J → « Lundi, le chargement n'a pas été vérifié sur deux palettes. »"], ["2", "F : date, action, quantité"], ["3", "J → « Cette fonction n'est pas testée. »"], ["4", "F : lieu, moment, nombre de fois"], ["5", "J → « Les trois dernières livraisons ont dépassé la date prévue. »"]], "erreurs": ["Croire qu'un adjectif est un fait : « négligent » ne se filme pas."]}}, "AX9": {"id": "AX9", "titre": "Dire non à la directrice : « oui, si… »", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 3", "situation": ["La directrice vous écrit : « Je veux le suivi des colis en temps réel pour notre client le plus important, dès demain. »", "Données : l'équipe informatique a 10 jours-homme disponibles ce mois-ci, dont 8 déjà engagés sur la migration du TMS. La demande représente environ 6 jours-homme."], "taches": ["Calculez la capacité disponible et le manque.", "Listez trois options (oui si, version réduite, nouveau délai) avec leur coût en jours-homme.", "Rédigez la réponse à la directrice en 5 lignes, décision proposée d'abord.", "Choisissez le canal (appel, e-mail) et justifiez.", "Quelle contrepartie demandez-vous à la direction ?"], "livrable": "Une réponse écrite de 5 lignes.", "corr": {"methode": ["Capacité disponible = capacité − engagements.", "Écart = demande − capacité disponible.", "Proposer des alternatives chiffrées, jamais un non sec.", "Mettre la décision d'abord, la contrainte ensuite."], "rows": [["Capacité disponible", "10 − 8 = 2 jours-homme"], ["Manque", "6 − 2 = 4 jours-homme"], ["Option 1 : oui, si", "Oui si la migration du TMS est décalée de 4 j-h (coût : migration retardée d'une semaine)"], ["Option 2 : version réduite", "2 j-h : alerte SMS de retard, sans suivi en temps réel complet"], ["Option 3 : délai", "Livrer la version complète dans 3 semaines, une fois la migration terminée"], ["Canal", "Appel puis e-mail de confirmation : la direction attend une décision, l'écrit garde la trace"]], "erreurs": ["Répondre « impossible » : la directrice cherche des options, pas un refus.", "Oublier de chiffrer les options en jours-homme : sans chiffre, l'arbitrage est impossible.", "Dire oui puis subir : un oui sans condition crée la dette de délai."], "modele": "« Bonjour, je vous propose de livrer demain une alerte SMS de retard (2 jours-homme, dans notre capacité) et la version complète dans 3 semaines, après la migration du TMS. La version complète demain exigerait de retarder la migration d'une semaine (4 jours-homme manquants). Quel arbitrage préférez-vous ? Je vous appelle à 14 h pour en discuter. »", "retenir": "« Oui, si… » : une décision proposée, des options chiffrées, une question d'arbitrage."}}, "AX10": {"id": "AX10", "titre": "Réécrire quatre messages de messagerie instantanée", "mode": "Individuel", "duree": 8, "chap": "Carnet · chapitre 4", "situation": ["Messages réellement envoyés (reconstitués) dans l'équipe de TransLor :", "1. « Ça marche pas. »", "2. « URGENT !!! Appelle-moi. »", "3. « Tu as vu mon mail ? »", "4. « Je ne suis pas d'accord. »"], "taches": ["Pour chaque message, identifiez ce qui manque.", "Réécrivez-le en 2 phrases maximum.", "Précisez le canal le plus adapté.", "Vérifiez que l'autre peut agir sans vous poser de question.", "Appliquez à un message de votre messagerie récente."], "livrable": "Quatre messages réécrits.", "corr": {"methode": ["Qui, quoi, où, quand, pour quand ?", "Mettre la demande en premier.", "Donner de quoi agir sans question supplémentaire."], "cols": ["Avant", "Défaut", "Après"], "widths": [1.6, 2.2, 4.6], "rows": [["« Ça marche pas. »", "Aucun objet, aucun contexte", "« L'application Tablette affiche l'erreur 504 depuis 6 h 40 sur 14 tablettes. Peux-tu regarder avant 8 h ? »"], ["« URGENT !!! Appelle-moi. »", "Anxiogène, sans raison", "« Un client conteste une livraison à 14 h. Peux-tu m'appeler avant 13 h 30 ? »"], ["« Tu as vu mon mail ? »", "Relance sans contenu", "« Pour la décision sur le transporteur, j'attends ton choix d'ici jeudi 12 h. »"], ["« Je ne suis pas d'accord. »", "Désaccord sans raison ni piste", "« Je ne vois pas comment tenir la date de vendredi. Que penses-tu de jeudi de la semaine prochaine ? »"]], "erreurs": ["Écrire « URGENT » sans dire pourquoi ni pour quand.", "Multiplier les points d'exclamation : le ton se lit comme de l'agressivité.", "Prendre une décision importante en message privé, sans trace partagée."]}}, "AX12": {"id": "AX12", "titre": "À / Cc / Cci, ton et droit à la déconnexion", "mode": "Binôme", "duree": 8, "chap": "Carnet · chapitre 4", "situation": ["E4 — Un développeur écrit à un client : « Salut, ton problème est réglé, c'était la faute de ton prestataire. » ; il met en copie toute l'équipe commerciale, et en copie cachée (Cci) son chef.", "E5 — Un chef de projet envoie à 22 h 15 à un collaborateur : « Il me faut ça demain 8 h, merci. »"], "taches": ["Pour E4 : relevez les problèmes de ton, de Cc et de Cci.", "Réécrivez E4 en trois phrases, vouvoiement.", "Pour E5 : quel est le problème ? Que proposer ?", "Rappelez la règle sur le droit à la déconnexion (cadre légal à vérifier).", "Écrivez la règle de messagerie que vous proposez pour TransLor."], "livrable": "Deux messages corrigés et une règle d'équipe.", "corr": {"methode": ["À = qui agit ; Cc = qui doit savoir ; Cci = exception, jamais pour surveiller.", "Faire descendre le ton d'un cran vers le neutre.", "Envoi différé pour respecter les horaires d'autrui."], "rows": [["E4 : problèmes", "Tutoiement avec un client ; reproche à un tiers ; Cc inutile (toute l'équipe) ; Cci d'un chef = défiance"], ["E4 : version corrigée", "« Bonjour Madame, le problème est résolu depuis 15 h. Il venait d'un paramétrage que nous avons corrigé. Nous restons disponibles. »"], ["E5 : problème", "Demande hors horaires, délai court : pression implicite"], ["E5 : solution", "Programmer l'envoi à 8 h 00 et demander une réponse avant 17 h"], ["Cadre légal", "Droit à la déconnexion : les modalités se négocient dans l'entreprise (Code du travail, art. L2242-17 — à vérifier)"], ["Règle TransLor", "Pas d'attente de réponse entre 19 h et 7 h 30 ; urgence = appel, pas message"]], "erreurs": ["Utiliser Cci pour « se couvrir » : si un chef doit savoir, il va en Cc.", "Penser que « urgent » justifie un envoi nocturne : prévoir un canal d'astreinte.", "Citer un article de loi de mémoire : toujours vérifier avant diffusion."]}}, "AX13": {"id": "AX13", "titre": "Rédiger un compte rendu de réunion", "mode": "Groupe de 3, document partagé", "duree": 12, "chap": "Carnet · chapitre 4", "situation": ["Notes brutes de la réunion « Dernier kilomètre » (9 personnes, 6 juin) :", "Directrice : lancement visé en septembre. — Marc : 14 tournées urbaines de plus, besoin de tablettes. — Admin : 2 jours-homme maximum, migration TMS d'abord. — Sonia : budget total 400 k€ pour 6 projets, ce projet 90 k€. — Décision : pilote à Nancy centre à partir du 15 septembre. — Marc liste les tournées avant le 30 juin. — Admin chiffre l'intégration avant le 5 juillet. — Paul : formation des conducteurs à planifier. — Sonia : budget validé en comité le 10 juillet. — Point ouvert : zones à faibles émissions, règles de circulation à vérifier."], "taches": ["Triez les notes : décisions, actions, points ouverts.", "Écrivez chaque action : qui / quoi / quand.", "Dans un document partagé, collez le modèle de la boîte à outils et rédigez le compte rendu (10 lignes maximum).", "Écrivez l'objet de l'e-mail d'envoi et les destinataires (À, Cc)."], "livrable": "Le compte rendu dans un document partagé (lien) avec le modèle.", "corr": {"methode": ["Trier les notes en trois catégories.", "Toute action = qui + quoi + quand.", "Décisions d'abord, actions ensuite, points ouverts à la fin.", "Envoyer sous 24 h."], "rows": [["Décision", "Pilote à Nancy centre à partir du 15 septembre"], ["Action 1", "Marc : lister les tournées urbaines avant le 30 juin"], ["Action 2", "Admin : chiffrer l'intégration avant le 5 juillet"], ["Action 3", "Sonia : faire valider le budget de 90 k€ au comité du 10 juillet"], ["Action 4", "Paul : proposer un calendrier de formation (date à fixer : à valider)"], ["Point ouvert", "Règles de circulation en zone à faibles émissions : responsable à désigner"]], "erreurs": ["Retranscrire la discussion au lieu des décisions.", "Action sans responsable ou sans date : elle ne sera pas faite.", "Envoyer le compte rendu une semaine après : la mémoire s'efface."], "modele": ["Objet : Compte rendu — Dernier kilomètre, 6 juin : pilote Nancy centre décidé", "Décision : pilote à Nancy centre à partir du 15 septembre. Budget visé : 90 k€ sur 400 k€ (6 projets).", "Actions : Marc, liste des tournées urbaines (14 de plus), avant le 30 juin. Admin, chiffrage de l'intégration (2 j-h maximum), avant le 5 juillet. Sonia, validation du budget, comité du 10 juillet. Paul, calendrier de formation des conducteurs, date à fixer.", "Point ouvert : règles en zone à faibles émissions, responsable à désigner. À : participants. Cc : directrice."], "retenir": "Un bon compte rendu se lit en 1 minute : décisions, actions (qui, quoi, quand), points ouverts."}}, "AX14": {"id": "AX14", "titre": "Écrire un ticket d'incident exploitable", "mode": "Binôme, GitHub Issues", "duree": 10, "chap": "Carnet · chapitre 4", "situation": ["Message reçu : « La synchro des tablettes ne marche plus depuis ce matin, c'est urgent, les gars sont bloqués. »", "Faits recueillis : début 6 h 40 ; 14 tablettes sur 60 touchées ; message d'erreur « 504 » ; problème sur le Wi-Fi du quai ; application version 3.2.1 ; dernier changement : mise à jour de dimanche ; les conducteurs peuvent travailler sur papier, avec 10 minutes de retard par tournée."], "taches": ["Ouvrez un ticket (GitHub Issues sur un dépôt de test) ou collez le modèle .md de la boîte à outils.", "Écrivez le titre (une ligne), puis contexte, impact, observé / attendu, étapes pour reproduire.", "Calculez la part de tablettes touchées et choisissez la priorité (P1 à P4) ; justifiez."], "livrable": "Un ticket complet (lien ou texte copié).", "corr": {"methode": ["Titre = où + quoi + quand.", "Impact en nombre de personnes et en temps.", "Observé / attendu / reproduire.", "Priorité selon une grille écrite."], "rows": [["Titre", "Tablettes conducteurs : erreur 504 à la synchro depuis 6 h 40 (Wi-Fi du quai)"], ["Part touchée", "14 / 60 = 23 % des tablettes"], ["Impact", "14 conducteurs sur papier, environ 10 minutes de retard par tournée"], ["Observé / attendu", "Observé : erreur 504 à la synchro. Attendu : synchro en moins de 30 s"], ["À reproduire / pièces", "Ouvrir l'application v3.2.1 sur le Wi-Fi du quai, lancer la synchro ; joindre une capture de l'erreur ; changement suspect : mise à jour de dimanche"], ["Priorité", "P2 : dégradation majeure avec contournement coûteux ; pas P1 car l'activité continue"]], "erreurs": ["Titre « urgent » sans information.", "Mélanger plusieurs problèmes dans un seul ticket.", "Oublier de mentionner le dernier changement : c'est la première piste de l'équipe technique."]}}, "AX15": {"id": "AX15", "titre": "Cartographier un argument : le modèle de Toulmin", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 5", "situation": ["Marc affirme : « TransLor doit passer aux camions électriques pour le dernier kilomètre. »", "Éléments disponibles : 14 tournées urbaines de 80 km par jour ; autonomie annoncée de 200 km (donnée du constructeur, non mesurée) ; zones à faibles émissions en extension ; aides à l'achat de véhicules propres ; prix d'achat plus élevé qu'un diesel."], "taches": ["Identifiez l'affirmation (A), les données (D), la garantie (G) qui relie D à A, le fondement (F) de la garantie.", "Formulez la réfutation possible (R) et la réserve (Q, « sauf si… »).", "Quelle donnée est la plus fragile ?", "Reformulez l'affirmation avec un qualificatif (probablement, dans les conditions…).", "Quelle preuve supplémentaire demandez-vous avant de décider ?"], "livrable": "Un schéma de Toulmin complété.", "corr": {"methode": ["Écrire l'affirmation en une phrase.", "Lister les données vérifiables.", "Expliciter la garantie : pourquoi ces données mènent à cette affirmation.", "Chercher la réfutation avant l'adversaire."], "cols": ["Élément", "Contenu"], "widths": [1.8, 6.4], "rows": [["Affirmation", "Passer aux camions électriques pour le dernier kilomètre"], ["Données", "80 km/jour pour 14 tournées ; autonomie 200 km ; extension des zones à faibles émissions ; aides"], ["Garantie", "Si l'autonomie couvre la tournée et que les zones restreignent le diesel, l'électrique est adapté"], ["Fondement", "Mesures d'autonomie réelles (hiver, chargement) et textes sur les zones"], ["Réfutation / réserve", "Autonomie réelle plus faible en hiver ; coût d'achat ; points de recharge : sauf si le coût total est supérieur"], ["Donnée fragile", "L'autonomie de 200 km est annoncée, non mesurée"]], "erreurs": ["Prendre la donnée du constructeur pour un fait établi.", "Oublier la garantie : l'argument semble évident, mais l'adversaire la conteste.", "Ne pas prévoir de réserve : l'argument paraît absolu et se brise sur la première objection."]}}, "AX16": {"id": "AX16", "titre": "Chasser les sophismes", "mode": "Binôme", "duree": 8, "chap": "Carnet · chapitre 5", "situation": ["Six phrases entendues en réunion :", "1. « Le concurrent X a des camions électriques, donc nous devons en acheter. »", "2. « Ce consultant n'a jamais conduit un camion, ignorez son rapport. »", "3. « Si on retarde le projet d'un mois, on perdra tous nos clients. »", "4. « Soit on passe tout à l'électrique, soit on disparaît. »", "5. « Deux conducteurs se sont plaints de la tablette, donc elle ne marche pas. »", "6. « Depuis le changement de TMS, les retards ont augmenté : le TMS est en cause. »"], "taches": ["Nommez le sophisme (popularité, attaque contre la personne, pente glissante, faux dilemme, généralisation hâtive, post hoc).", "Expliquez en une phrase pourquoi le raisonnement est fragile.", "Écrivez une contre-question.", "Citez une phrase de ce type que vous avez entendue en entreprise.", "Reformulez la phrase 6 comme une hypothèse à tester."], "livrable": "Un tableau sophisme / explication / contre-question.", "corr": {"methode": ["Chercher le lien logique entre l'affirmation et la raison donnée.", "Nommer le procédé.", "Répondre par une question, pas par une accusation."], "cols": ["N°", "Sophisme", "Contre-question"], "widths": [0.5, 2.2, 5.5], "rows": [["1", "Appel à la popularité", "« Leur contexte est-il le même que le nôtre ? »"], ["2", "Attaque contre la personne", "« Quels points du rapport sont faux ? »"], ["3", "Pente glissante", "« Quelles preuves relient un mois de retard à la perte de tous les clients ? »"], ["4", "Faux dilemme", "« Existe-t-il une étape intermédiaire, comme un pilote ? »"], ["5", "Généralisation hâtive", "« Combien de tablettes sont touchées sur 60 ? »"], ["6", "Post hoc (corrélation prise pour cause)", "« Qu'a-t-il changé d'autre en même temps ? Comparons avec les mois précédents. »"]], "erreurs": ["Traiter l'interlocuteur de « sophiste » : cela devient une attaque personnelle.", "Croire qu'un argument faux oblige à rejeter la conclusion : la conclusion peut rester vraie, mais non prouvée."]}}, "AX17": {"id": "AX17", "titre": "Évaluer cinq sources", "mode": "Binôme", "duree": 15, "chap": "Carnet · chapitre 5", "situation": ["Sujet : les camions électriques en milieu urbain. Cinq sources (fictives) :", "S1 — Article de revue à comité de lecture, 2024, méthode décrite, 3 villes, limites discutées.", "S2 — Brochure commerciale d'un constructeur, 2025, chiffres sans méthode.", "S3 — Rapport d'une agence publique, 2023, mesures sur 120 véhicules, méthode publiée.", "S4 — Billet de blog anonyme, 2022, « 100 % rentable » sans source.", "S5 — Article de presse généraliste, 2025, cite uniquement S2."], "taches": ["Notez chaque source de 0 à 2 sur 6 critères : Qui ? Quand ? Pourquoi ? Sur quoi (preuves) ? Recoupé ? Reproductible ? (maximum 12).", "Seuils : 9 et plus fiable ; 5 à 8 à recouper ; 4 et moins à écarter ou à citer avec prudence.", "Classez les sources.", "Que gardez-vous pour un état de l'art ?", "Pourquoi S5 n'ajoute-t-elle rien à S2 ?"], "livrable": "Un tableau de notation et la liste des sources retenues.", "corr": {"methode": ["Qui : auteur identifié et compétent ? Quand : récent pour le sujet ? Pourquoi : informer ou vendre ?", "Sur quoi : données et méthode visibles ? Recoupé : d'autres sources concordent ? Reproductible : méthode refaisable ?", "Additionner puis appliquer les seuils."], "cols": ["Source", "Q / Q / P / S / R / R", "Total", "Décision"], "widths": [0.7, 2.4, 0.9, 4.2], "rows": [["S1", "2 / 2 / 2 / 2 / 1 / 2", "11", "Fiable : retenue"], ["S3", "2 / 1 / 2 / 2 / 1 / 2", "10", "Fiable : retenue"], ["S5", "1 / 2 / 1 / 0 / 0 / 0", "4", "À écarter : source unique, reprend S2"], ["S2", "1 / 2 / 0 / 0 / 0 / 0", "3", "Citer comme position du constructeur seulement"], ["S4", "0 / 1 / 0 / 0 / 0 / 0", "1", "Écartée"]], "erreurs": ["Croire qu'un chiffre cité plusieurs fois est vrai : S5 dépend de S2 (source circulaire).", "Rejeter une brochure commerciale : on peut la citer comme position de l'acteur.", "Retenir seulement les sources qui confirment son idée (biais de confirmation)."]}}, "AX18": {"id": "AX18", "titre": "Mini état de l'art : comparer trois solutions de verdissement", "mode": "Groupe de 3", "duree": 20, "chap": "Carnet · chapitre 5", "situation": ["Pour le dernier kilomètre, trois solutions (scores fictifs de 1 à 5, 5 = meilleur) :", "Électrique : coût 3, autonomie 2, émissions 5, disponibilité 3.", "BioGNV : coût 4, autonomie 4, émissions 4, disponibilité 3.", "HVO (biocarburant pour moteur diesel) : coût 4, autonomie 5, émissions 3, disponibilité 4.", "Pondérations de départ : coût 30 %, autonomie 25 %, émissions 25 %, disponibilité 20 %."], "taches": ["Calculez la note pondérée de chaque solution.", "Classez-les.", "Test de sensibilité : émissions 40 %, les autres 20 % chacune. Le classement change-t-il ?", "Rédigez la conclusion en 3 phrases avec un qualificatif et une réserve.", "Quelles données réelles faudrait-il collecter avant de décider ?"], "livrable": "Tableau de calcul et conclusion rédigée.", "corr": {"methode": ["Note = somme (score × poids).", "Refaire avec d'autres poids pour voir si le classement est stable.", "Conclure avec réserve : les scores sont fictifs et à sourcer."], "cols": ["Solution", "Base (30/25/25/20)", "Émissions 40 % (20/20/40/20)"], "widths": [1.6, 3.2, 3.5], "rows": [["Électrique", "0,9 + 0,5 + 1,25 + 0,6 = 3,25", "0,6 + 0,4 + 2,0 + 0,6 = 3,60"], ["BioGNV", "1,2 + 1,0 + 1,0 + 0,6 = 3,80", "0,8 + 0,8 + 1,6 + 0,6 = 3,80"], ["HVO", "1,2 + 1,25 + 0,75 + 0,8 = 4,00", "0,8 + 1,0 + 1,2 + 0,8 = 3,80"], ["Classement", "HVO > BioGNV > Électrique", "BioGNV = HVO (3,80) > Électrique (3,60)"], ["Lecture", "Le choix dépend de la pondération : les pondérations sont un argument, pas un fait", ""]], "erreurs": ["Présenter un classement sans test de sensibilité : il peut s'inverser avec d'autres poids.", "Oublier que les scores sont des données à sourcer, pas des vérités.", "Conclure sans réserve : « le HVO est le meilleur » alors que l'écart est faible."], "modele": "« Sous les pondérations actuelles, le HVO paraît la solution la plus adaptée (4,00 contre 3,80 et 3,25). Si les émissions deviennent la priorité (40 %), le HVO et le bioGNV sont à égalité (3,80). Avant de décider, il faut vérifier les scores sur des sources mesurées (autonomie réelle, disponibilité locale) ; ces notes sont fictives. »", "retenir": "Un état de l'art honnête : critères explicites, test de sensibilité, réserve, sources à vérifier."}}, "AX19": {"id": "AX19", "titre": "Synthèse du jour 1 : une situation de communication complète", "mode": "Binôme", "duree": 25, "chap": "Carnet · chapitres 2 à 4", "situation": ["Paul (DRH) écrit à Marc, copie à la directrice : « Encore un planning de formation changé sans me prévenir. Vous faites n'importe quoi à l'exploitation. »", "Faits : le planning a été modifié mardi pour absorber une absence ; Paul n'a pas été prévenu ; 4 conducteurs étaient convoqués à une formation obligatoire."], "taches": ["Quel niveau d'écoute Paul attend-il ? Écrivez une reformulation en 2 phrases.", "Formulez un feedback SBI sur le message de Paul (comportement : copie à la directrice et ton).", "Choisissez le canal pour répondre : appel ou e-mail ? Justifiez.", "Rédigez l'e-mail de confirmation en 8 lignes maximum, conclusion d'abord.", "Proposez une règle pour éviter la répétition."], "livrable": "Un appel préparé (3 phrases) et un e-mail.", "corr": {"methode": ["Écouter d'abord : reconnaître l'émotion et le fait.", "Feedback SBI sans jugement sur la personne.", "Appeler pour l'émotion, écrire pour la trace.", "Terminer par une règle ou une action datée."], "rows": [["Reformulation", "« Vous découvrez un changement qui touche une formation obligatoire, et vous n'avez pas été prévenu. C'est cela ? »"], ["SBI", "« Dans votre message de ce matin copié à la directrice, la phrase « n'importe quoi » ne m'aide pas à corriger ; j'aimerais qu'on parle d'abord des 4 conducteurs. »"], ["Canal", "Appel immédiat (émotion), puis e-mail pour confirmer la décision"], ["Action", "Marc informe Paul avant tout changement qui touche une formation (message avant 16 h la veille)"], ["Règle", "Un changement de planning de formation = information du RH en 2 heures, via un canal partagé"]], "erreurs": ["Répondre à chaud par écrit avec la directrice en copie : le conflit s'amplifie.", "S'excuser sans corriger la cause : la même situation reviendra.", "Oublier les 4 conducteurs : c'est l'impact réel."], "modele": "Objet : Planning de formation du 12 — conducteurs confirmés\n\nPaul, suite à notre échange de 10 h : les 4 conducteurs seront convoqués à la formation du jeudi 14 à 9 h ; vous recevrez désormais tout changement dans les 2 heures par message partagé. Je suis désolé de ne pas vous avoir prévenu mardi. Je vous confirme la liste avant 16 h. Marc", "retenir": "Écouter, appeler, confirmer par écrit, fixer une règle."}}, "AF5": {"id": "AF5", "titre": "Flash · Messagerie instantanée : vrai ou faux ?", "mode": "Solo puis voisin", "duree": 3, "chap": "Carnet · chapitre 4", "situation": ["1. Écrire « Bonjour » seul et attendre une réponse est une bonne pratique.", "2. Utiliser @tous pour une information non urgente est acceptable.", "3. Répondre dans le fil (thread) aide à garder les sujets séparés.", "4. Une décision importante prise en message privé n'a pas besoin de trace partagée.", "5. Les émojis sont acceptables selon la culture de l'équipe."], "taches": ["Répondez Vrai ou Faux.", "Corrigez les affirmations fausses.", "Écrivez une règle de messagerie pour TransLor."], "livrable": "", "corr": {"methode": ["Penser à l'autre : peut-il agir sans poser de question ?"], "rows": [["1", "Faux : « Bonjour + la question complète »"], ["2", "Faux : réserver @tous aux urgences"], ["3", "Vrai"], ["4", "Faux : consigner dans un canal ou un compte rendu"], ["5", "Vrai : se mettre d'accord sur les usages"]], "erreurs": ["Attendre le « bonjour » de l'autre avant d'écrire la question : on perd du temps à chaque échange."]}}, "AX20": {"id": "AX20", "titre": "Pitch de 2 minutes : le projet « dernier kilomètre »", "mode": "Groupe de 3", "duree": 30, "chap": "Carnet · chapitre 6", "situation": ["Public : la directrice de TransLor (non technique) et le comité de direction. Sujet : le projet de dernier kilomètre en ville (pilote à Nancy centre le 15 septembre, 90 k€ sur 400 k€, 14 tournées urbaines de 80 km par jour).", "Contrainte : 2 minutes, sans diapositive, un message clé.", "Organisation : 10 minutes de préparation individuelle ; 3 × (2 min de pitch + 3 min de retour) en groupe de 3."], "taches": ["Écrivez votre message clé en une phrase.", "Construisez le plan : accroche, problème, solution, preuve, appel à décision.", "Préparez une analogie et un chiffre.", "Pitchez 2 minutes (chronométrées).", "Évaluez vos deux pairs avec la grille sur 20 : accroche 3, message clé 4, structure 4, clarté 4, voix et posture 3, appel à décision 2."], "livrable": "Votre message clé et la grille de vos pairs.", "corr": {"methode": ["Message clé : une phrase que la directrice peut répéter.", "Accroche : un fait ou une scène, pas « bonjour, je vais vous parler de… ».", "Un chiffre, une analogie, une demande.", "S'entraîner à voix haute avec un chronomètre."], "cols": ["Critère", "Points", "Ce qui vaut le maximum"], "widths": [2.2, 0.9, 5.2], "rows": [["Accroche", "3", "Scène ou chiffre qui crée l'attention en 10 secondes"], ["Message clé", "4", "Une phrase claire, répétée à la fin"], ["Structure", "4", "Problème, solution, preuve, appel enchaînés sans digression"], ["Clarté / vulgarisation", "4", "Aucun jargon non expliqué ; une analogie"], ["Voix et posture", "3", "Débit calme, pauses, regard, mains visibles"], ["Appel à décision", "2", "Une demande datée et chiffrée (total : 20)"]], "erreurs": ["Lire ses notes : on perd le regard et la voix.", "Vouloir tout dire : 2 minutes = 1 message.", "Terminer par « voilà, c'est tout » au lieu d'une demande."], "modele_titre": "Exemple modèle (moins de 2 minutes)", "modele": "« Lundi, 7 h : quatorze tournées urbaines quittent Nancy, et 12 % dépassent le créneau promis à nos clients. Nos trois plus gros clients, 60 % de notre chiffre d'affaires, pénalisent les retards. Notre projet : un pilote de dernier kilomètre à Nancy centre à partir du 15 septembre, avec des véhicules propres adaptés à 80 km par jour et une alerte de retard 30 minutes avant le créneau. Pourquoi cela marche : les tournées urbaines sont courtes, l'e-commerce progresse et les zones à faibles émissions arrivent. Il demande 90 k€ sur les 400 k€ des six projets, et nous permet de mesurer avant d'étendre. Les risques : autonomie en hiver, disponibilité des véhicules ; nous les suivons avec deux indicateurs, taux de retard et kilomètres réels. Ce que je vous demande aujourd'hui : valider le pilote et ses 90 k€ au comité du 10 juillet. »", "retenir": "Accroche, problème, solution, preuve, risque, appel : une idée par phrase."}}, "AX21": {"id": "AX21", "titre": "Répondre aux objections de la directrice", "mode": "Binôme", "duree": 12, "chap": "Carnet · chapitre 6", "situation": ["Après votre pitch, la directrice objecte :", "1. « Pourquoi ne pas simplement sous-traiter le dernier kilomètre ? »", "2. « C'est trop cher. »", "3. « Et si les clients n'en veulent pas ? »"], "taches": ["Pour chaque objection, reformulez l'inquiétude derrière (1 phrase).", "Répondez avec un fait ou un chiffre (2 phrases).", "Terminez par une vérification : « Cela répond-il à votre inquiétude ? »", "Calculez la part du budget : 90 k€ sur 400 k€.", "Jouez l'échange à deux, 3 minutes, avec un observateur."], "livrable": "Trois réponses structurées.", "corr": {"methode": ["Écouter sans interrompre.", "Reformuler l'inquiétude.", "Répondre avec un fait ou un chiffre.", "Vérifier : « Cela répond-il à votre question ? »"], "cols": ["Objection", "Reformulation", "Réponse modèle"], "widths": [1.8, 2.5, 4.2], "rows": [["Sous-traiter ?", "« Vous craignez d'investir dans une activité que d'autres savent faire ? »", "« Sous-traiter limite l'investissement, mais nous perdons la relation client et les données. Le pilote nous permet de comparer le coût par livraison. »"], ["Trop cher", "« 90 k€ vous semblent élevés ? »", "« C'est 22,5 % du budget de 400 k€ (90 / 400). Le pilote limite le risque : nous mesurons avant d'étendre. »"], ["Clients ?", "« Vous voulez être sûre de la demande avant d'engager ? »", "« Le pilote se fait avec des clients volontaires ; nous fixons un seuil d'arrêt à 3 mois. Cela répond-il à votre inquiétude ? »"]], "erreurs": ["Se défendre avant d'avoir compris l'objection.", "Répondre à côté : la question pose un risque, la réponse parle d'un avantage.", "Mentir ou inventer un chiffre : « je reviens vers vous avec la source » est meilleur."]}}, "AF7": {"id": "AF7", "titre": "Flash · Combien coûte une réunion ?", "mode": "Binôme", "duree": 4, "chap": "Carnet · chapitre 7", "situation": ["Réunion hebdomadaire : 8 participants, 1 heure, 45 semaines par an, coût horaire chargé 32 €."], "taches": ["Calculez le coût d'une réunion et le coût annuel.", "Économie si 3 participants inutiles ne viennent plus.", "Économie si la durée passe à 30 minutes.", "Combinez les deux : coût annuel et économie."], "livrable": "", "corr": {"methode": ["Coût = participants × durée × coût horaire.", "Annuel = coût × nombre de semaines."], "rows": [["Une réunion", "8 × 1 × 32 = 256 €"], ["Par an", "256 × 45 = 11 520 €"], ["3 participants en moins", "5 × 32 × 45 = 7 200 € ; économie 4 320 €"], ["30 minutes", "8 × 0,5 × 32 × 45 = 5 760 € ; économie 5 760 €"], ["Les deux", "5 × 0,5 × 32 × 45 = 3 600 € ; économie 7 920 €"]], "erreurs": ["Compter seulement la durée et oublier le coût des participants.", "Conclure qu'il faut supprimer la réunion : l'objectif est une réunion utile, pas aucune."]}}, "AX22": {"id": "AX22", "titre": "Annoncer le report du pilote", "mode": "Binôme", "duree": 10, "chap": "Carnet · chapitre 7", "situation": ["Le pilote à Nancy centre prévu le 15 septembre est reporté de 8 semaines (nouvelle date : 10 novembre) car la livraison des véhicules est retardée. 14 tournées urbaines sont concernées.", "Publics : les conducteurs, les gestionnaires, trois clients impliqués, la directrice."], "taches": ["Identifiez les publics et ce que chacun veut savoir.", "Structure : fait, cause, impact, plan, soutien, prochain point.", "Rédigez l'annonce aux conducteurs en 6 lignes.", "Choisissez le canal et le moment pour chaque public.", "Anticipez deux questions difficiles et leurs réponses."], "livrable": "L'annonce aux conducteurs.", "corr": {"methode": ["Fait d'abord, sans enrobage.", "Cause factuelle, sans chercher de coupable.", "Impact sur le public concerné.", "Plan et prochaine information datée."], "rows": [["Directrice", "Avant tout le monde : appel, 5 minutes (décision et plan)"], ["Conducteurs", "Réunion courte puis message écrit le même jour"], ["Clients", "Appel personnalisé du responsable, puis e-mail"], ["Questions difficiles", "« Pourquoi si tard ? » : date de la notification fournisseur. « Mes tournées changent-elles ? » : non avant le 10 novembre"]], "erreurs": ["Annoncer par e-mail sans l'expliquer à l'oral : les rumeurs partent.", "Minimiser : « petit retard » pour 8 semaines.", "Promettre une date sans l'avoir confirmée avec le fournisseur."], "modele": "« Le pilote du dernier kilomètre ne démarrera pas le 15 septembre mais le 10 novembre, soit 8 semaines plus tard. La cause : la livraison des véhicules est retardée par le constructeur. Vos tournées actuelles ne changent pas avant cette date. La formation est reportée en conséquence. Je vous donne un point d'étape le 15 octobre et je reste disponible après la réunion pour vos questions. »", "retenir": "Fait, cause, impact, plan, prochain point : dans cet ordre, sans minimiser."}}, "AX23": {"id": "AX23", "titre": "Réunion tendue : exploitation contre informatique", "mode": "Groupe de 4", "duree": 12, "chap": "Carnet · chapitre 7", "situation": ["Rôles : Marc (exploitation), Admin (informatique), animateur, observateur.", "Marc : « L'informatique ne comprend rien à nos contraintes. » Admin : « Vous nous envoyez vos demandes à la dernière minute. »", "Mission de l'animateur : en 10 minutes, obtenir deux engagements (qui, quoi, quand). L'observateur remplit la grille."], "taches": ["Animateur : poser le cadre (objectif, durée, règles).", "Reformuler chaque position et séparer faits et jugements.", "Chercher un intérêt commun.", "Obtenir deux engagements datés.", "Observateur : noter les reformulations, les jugements évités, les engagements obtenus."], "livrable": "Deux engagements écrits et la grille remplie.", "corr": {"methode": ["Cadre : objectif, durée, règle de parole.", "Reformuler, puis séparer faits et jugements.", "Chercher l'intérêt commun.", "Conclure par des engagements qui / quoi / quand."], "cols": ["Moment", "Phrase d'animateur"], "widths": [1.8, 6.4], "rows": [["Cadre", "« Nous avons 10 minutes pour sortir avec deux engagements, chacun parle à son tour. »"], ["Reformuler", "« Marc, vous avez besoin d'une réponse rapide ; Admin, vous avez besoin de délais réalistes. »"], ["Faits / jugements", "« Combien de demandes sont arrivées à moins de 24 h le mois dernier ? »"], ["Intérêt commun", "« Vous voulez tous les deux des tournées sans panne. »"], ["Engagements", "Marc dépose ses demandes par ticket avant 16 h pour J+2 ; Admin répond sous 24 h avec une estimation"]], "erreurs": ["Donner raison à l'un des deux : l'animateur perd sa neutralité.", "Rester sur des jugements (« ne comprend rien ») sans mesurer.", "Terminer sans engagement daté : la tension reviendra."]}}, "AX24": {"id": "AX24", "titre": "Mon plan d'action 30-60-90 jours", "mode": "Individuel puis binôme", "duree": 15, "chap": "Carnet · chapitre 8", "situation": ["Vous avez vu écoute, affirmation, écrit, argumentation, oral et gestion de la tension. Choisissez trois compétences à progresser dans votre contexte (alternance, stage, projet)."], "taches": ["Choisissez 3 compétences.", "Pour chacune, une action à 30 jours, une à 60 jours, une à 90 jours.", "Un indicateur mesurable par action.", "Un premier pas demain (moins de 15 minutes).", "Partagez-le avec votre voisin et fixez une date de point."], "livrable": "Le plan rempli dans le carnet.", "corr": {"methode": ["Une compétence = une action observable.", "Indicateur chiffré ou daté.", "Premier pas demain : se rendre un engagement impossible à ignorer."], "cols": ["Compétence", "30 jours", "60 jours", "90 jours"], "widths": [1.7, 2.2, 2.2, 2.2], "rows": [["Écoute", "Reformuler dans 3 entretiens", "Faire une triade avec un collègue", "Recueillir un besoin et le faire valider"], ["Écrit", "Objet précis sur 100 % de mes e-mails", "Compte rendu sous 24 h", "Un ticket ou une note de synthèse relue"], ["Oral", "Pitch de 2 min devant un pair", "Prise de parole en réunion d'équipe", "Présentation à un public averti"]], "erreurs": ["Plan trop large : trois compétences, pas six.", "Aucune date de point : sans suivi, le plan s'oublie.", "Objectifs vagues : « mieux communiquer »."]}}, "AF8": {"id": "AF8", "titre": "Exit ticket · fin du jour 1", "mode": "Individuel", "duree": 5, "chap": "Carnet · tous chapitres", "situation": ["Sur une demi-page du carnet, en 5 minutes."], "taches": ["Une idée que je retiens du jour 1.", "Une pratique que j'applique dès demain.", "Une question ou une difficulté qui reste.", "Un exemple de TransLor qui m'a aidé."], "livrable": ""}, "AF0": {"id": "AF0", "titre": "Accroche · Le SMS de la directrice", "mode": "Binôme", "duree": 5, "chap": "Carnet · chapitre 1", "situation": ["La directrice envoie ce SMS à Marc à 6 h 30 : « Décale le chargement de 14 h, il est prioritaire. »", "Marc a une réunion à 7 h. Il ne peut pas la joindre avant 10 h."], "taches": ["Combien de lectures différentes du message trouvez-vous ? Au moins quatre.", "Qu'est-ce qui manque pour agir sans risque ?", "Réécrivez le SMS en une ligne."], "livrable": "", "corr": {"methode": ["Lire mot à mot : verbe, objet, moment, personne.", "Lister ce qui est implicite.", "Réécrire avec qui, quoi, quand."], "rows": [["« Décale »", "Avancer ou retarder ? De combien ?"], ["« le chargement de 14 h »", "Lequel, s'il y en a plusieurs à cette heure ?"], ["« il est prioritaire »", "Le chargement décalé, ou celui qui prend sa place ?"], ["Ce qui manque", "Nouvel horaire, raison, qui prévenir"], ["Version claire", "« Marc, avance le chargement du client A de 14 h à 12 h, il passe avant les autres. Préviens les conducteurs. »"]], "erreurs": ["Agir sans vérifier : si Marc se trompe, le retard est pour lui.", "Reprocher à la directrice : elle est pressée, la clarification est à la charge des deux."]}}}, "quiz": [{"id": "G01", "fam": "G", "famille": "Argumenter et informer", "pts": 1, "q": "Dans le modèle de Toulmin, la garantie…", "options": ["relie les données à l'affirmation", "est la conclusion", "est la preuve chiffrée", "est la réfutation"], "bonne": 0, "expl": "Elle explicite pourquoi ces données mènent à cette conclusion."}, {"id": "G02", "fam": "G", "famille": "Argumenter et informer", "pts": 1, "q": "« Tout le monde le fait, donc nous devons le faire. » Quel sophisme ?", "options": ["Attaque contre la personne", "Appel à la popularité", "Pente glissante", "Faux dilemme"], "bonne": 1, "expl": "Ce que font les autres ne prouve pas que ce soit adapté à notre cas."}, {"id": "G03", "fam": "G", "famille": "Argumenter et informer", "pts": 1, "q": "Qu'est-ce qu'une source primaire ?", "options": ["Un article de presse qui cite un rapport", "Une encyclopédie", "Les données ou le témoignage d'origine, comme un rapport d'essai", "Un manuel de cours"], "bonne": 2, "expl": "On remonte à l'origine de l'information."}, {"id": "G04", "fam": "G", "famille": "Argumenter et informer", "pts": 2, "q": "Premier réflexe pour valider une affirmation chiffrée ?", "options": ["La répéter si elle est citée souvent", "Prendre la plus récente", "Demander à un collègue", "Remonter à la source d'origine et la recouper"], "bonne": 3, "expl": "Un chiffre cité plusieurs fois peut venir d'une seule source."}, {"id": "G05", "fam": "G", "famille": "Argumenter et informer", "pts": 2, "q": "Le biais de confirmation, c'est…", "options": ["chercher surtout ce qui confirme son idée de départ", "croire les experts", "douter de tout", "oublier les chiffres"], "bonne": 0, "expl": "On corrige en cherchant des arguments contraires."}, {"id": "G06", "fam": "G", "famille": "Argumenter et informer", "pts": 2, "q": "Un état de l'art, c'est…", "options": ["une liste de sources", "un panorama comparé et critique des solutions selon des critères explicites", "un résumé d'un seul article", "une opinion argumentée"], "bonne": 1, "expl": "Il compare, il ne fait pas que lister."}, {"id": "G07", "fam": "G", "famille": "Argumenter et informer", "pts": 3, "q": "Une IA générative propose une référence bibliographique. Que faire ?", "options": ["La citer telle quelle", "La citer si le titre est crédible", "Vérifier qu'elle existe réellement avant de la citer", "La supprimer sans vérifier"], "bonne": 2, "expl": "Ces outils peuvent produire des références inexistantes."}, {"id": "R01", "fam": "R", "famille": "Chercher l'information", "pts": 1, "q": "Dans Google Scholar, que font les guillemets autour de plusieurs mots ?", "options": ["Ils excluent ces mots", "Ils limitent aux articles récents", "Ils cherchent seulement dans le titre", "Ils cherchent l'expression exacte"], "bonne": 3, "expl": "Les guillemets cherchent la suite exacte de mots ; le tiret exclut un mot ; la période se règle avec le filtre de dates."}, {"id": "R02", "fam": "R", "famille": "Chercher l'information", "pts": 1, "q": "Quel opérateur permet d'accepter plusieurs synonymes dans une même requête ?", "options": ["OR (ou)", "Le tiret devant le mot", "Les guillemets", "Le point d'exclamation"], "bonne": 0, "expl": "« cloud » OR « nuage » accepte les deux termes ; le tiret exclut, les guillemets fixent une expression."}, {"id": "R03", "fam": "R", "famille": "Chercher l'information", "pts": 1, "q": "Pourquoi chercher aussi en anglais sur un sujet technique ?", "options": ["Les sources françaises sont toujours moins fiables", "Une grande part des publications techniques y est écrite", "Pour obtenir plus de résultats, quelle que soit leur qualité", "Parce que Scholar refuse le français"], "bonne": 1, "expl": "Chercher dans les deux langues élargit le panorama ; cela ne dit rien de la fiabilité des sources françaises."}, {"id": "R04", "fam": "R", "famille": "Chercher l'information", "pts": 2, "q": "Quelle est la première étape d'une démarche de recherche ?", "options": ["Ouvrir un moteur de recherche", "Lire le premier résultat", "Préciser la question et le besoin", "Rédiger la conclusion"], "bonne": 2, "expl": "Sans question précise, on cherche au hasard et on ne sait pas quand s'arrêter."}, {"id": "R05", "fam": "R", "famille": "Chercher l'information", "pts": 2, "q": "Où trouver un guide officiel de bonnes pratiques de cybersécurité en France ?", "options": ["Sur un forum anonyme", "Dans une brochure commerciale", "Sur un réseau social", "Sur le site d'une agence publique (par exemple l'ANSSI)"], "bonne": 3, "expl": "Les agences publiques publient des guides sourcés : vérifiez la date et la version."}, {"id": "R06", "fam": "R", "famille": "Chercher l'information", "pts": 2, "q": "Pourquoi noter la référence dès la première lecture ?", "options": ["Pour retrouver et citer la source sans la rechercher à nouveau", "Pour allonger la bibliographie", "Parce que cela se fait sans raison", "Pour éviter de lire l'article"], "bonne": 0, "expl": "Retrouver une source oubliée coûte du temps ; l'outil de références (Zotero) la garde en un clic."}, {"id": "R07", "fam": "R", "famille": "Chercher l'information", "pts": 3, "q": "Que permet un outil comme Zotero ?", "options": ["Vérifier automatiquement qu'une source est fiable", "Enregistrer, classer et citer des références", "Traduire les articles", "Écrire l'état de l'art à votre place"], "bonne": 1, "expl": "Il gère les références ; la fiabilité reste à évaluer par vous."}, {"id": "R08", "fam": "R", "famille": "Chercher l'information", "pts": 3, "q": "Votre première requête donne 40 000 résultats. Que faites-vous ?", "options": ["Lire les 100 premiers", "Ne garder que la première page", "La préciser : mots plus spécifiques, guillemets, filtre de dates", "Abandonner la question"], "bonne": 2, "expl": "Une requête trop large se resserre ; on note la requête exacte pour pouvoir la refaire."}, {"id": "V01", "fam": "V", "famille": "Évaluer et valider", "pts": 1, "q": "Un article cite une étude sans donner sa méthode. Que faites-vous ?", "options": ["La citer telle quelle", "La considérer comme fausse", "La recopier avec les mêmes mots", "Chercher l'étude d'origine avant de la citer"], "bonne": 3, "expl": "Remonter à la source d'origine permet de juger la méthode, ou de constater qu'elle n'existe pas."}, {"id": "V02", "fam": "V", "famille": "Évaluer et valider", "pts": 1, "q": "Deux articles donnent le même chiffre ; tous deux citent la même brochure commerciale. Combien de sources indépendantes ?", "options": ["Une seule : la brochure", "Deux", "Trois", "Aucune"], "bonne": 0, "expl": "Deux citations d'une même source ne la recoupent pas : c'est une source circulaire."}, {"id": "V03", "fam": "V", "famille": "Évaluer et valider", "pts": 1, "q": "Qu'est-ce qu'un preprint ?", "options": ["Un article rejeté par une revue", "Un article diffusé avant relecture par des pairs", "Un article de presse", "Un article déjà validé par une revue"], "bonne": 1, "expl": "Un preprint n'a pas encore été évalué par des pairs : à utiliser avec prudence et à signaler."}, {"id": "V04", "fam": "V", "famille": "Évaluer et valider", "pts": 2, "q": "Qu'est-ce qui rend une brochure commerciale à utiliser avec prudence ?", "options": ["Elle est récente", "Elle est mise en page avec soin", "Son but est de vendre : elle présente ses propres résultats, souvent sans méthode", "Elle est écrite en anglais"], "bonne": 2, "expl": "On peut la citer comme position de l'acteur, pas comme preuve."}, {"id": "V05", "fam": "V", "famille": "Évaluer et valider", "pts": 2, "q": "Une référence proposée par une IA générative semble parfaite. Que faire avant de la citer ?", "options": ["La citer : l'IA est fiable", "Demander à la même IA de confirmer", "La citer sans l'année", "Vérifier qu'elle existe (auteurs, revue, adresse DOI)"], "bonne": 3, "expl": "Une IA peut inventer des références plausibles ; lui demander de confirmer ne prouve rien."}, {"id": "V06", "fam": "V", "famille": "Évaluer et valider", "pts": 2, "q": "Le biais de confirmation consiste à…", "options": ["retenir surtout les sources qui confirment son idée", "citer trop de sources", "ne chercher que des sources récentes", "ne citer que des sources en anglais"], "bonne": 0, "expl": "Chercher aussi ce qui contredit son idée protège contre ce biais."}, {"id": "V07", "fam": "V", "famille": "Évaluer et valider", "pts": 3, "q": "Une donnée de 2012 sur les usages du cloud : quel est le problème principal ?", "options": ["Elle est forcément fausse", "Elle peut être périmée dans un domaine qui évolue vite", "Elle est trop précise", "Elle est en chiffres"], "bonne": 1, "expl": "La date doit correspondre au sujet : en informatique, quelques années suffisent à changer la donne."}, {"id": "V08", "fam": "V", "famille": "Évaluer et valider", "pts": 3, "q": "Qu'est-ce qui distingue le mieux une revue à comité de lecture d'un blog ?", "options": ["Le nombre de lecteurs", "La longueur des textes", "Des experts indépendants évaluent l'article avant publication", "La présence d'images"], "bonne": 2, "expl": "La relecture par des pairs filtre une partie des erreurs, sans les supprimer toutes."}, {"id": "T01", "fam": "T", "famille": "Argumenter", "pts": 1, "q": "Dans le modèle de Toulmin, que désigne la « garantie » ?", "options": ["La conclusion", "La source du chiffre", "La liste des objections", "Le lien qui explique pourquoi les données mènent à l'affirmation"], "bonne": 3, "expl": "Données + garantie → affirmation : sans garantie, les faits ne prouvent rien."}, {"id": "T02", "fam": "T", "famille": "Argumenter", "pts": 1, "q": "Que représente la « réfutation » dans le modèle de Toulmin ?", "options": ["Les cas où l'argument ne tient pas", "La réponse de l'adversaire", "Le résumé final", "La source principale"], "bonne": 0, "expl": "La chercher soi-même rend la conclusion plus honnête et plus crédible."}, {"id": "T03", "fam": "T", "famille": "Argumenter", "pts": 1, "q": "« Tout le monde passe au cloud, faisons pareil » est un exemple de…", "options": ["pente glissante", "appel à la popularité", "faux dilemme", "post hoc"], "bonne": 1, "expl": "Le nombre de personnes qui font une chose ne prouve pas qu'elle convient à votre cas."}, {"id": "T04", "fam": "T", "famille": "Argumenter", "pts": 2, "q": "« Soit on achète cet outil, soit on se fait pirater » est un…", "options": ["appel à la popularité", "généralisation hâtive", "faux dilemme", "attaque contre la personne"], "bonne": 2, "expl": "D'autres options existent presque toujours : il faut les chercher."}, {"id": "T05", "fam": "T", "famille": "Argumenter", "pts": 2, "q": "Un fournisseur annonce « 99 % d'incidents en moins ». Quelle première question posez-vous ?", "options": ["Quel est son prix ?", "Est-il connu ?", "La page est-elle bien mise en forme ?", "Par rapport à quoi, mesuré comment, sur quel échantillon ?"], "bonne": 3, "expl": "Un chiffre sans base de comparaison, méthode ni échantillon ne prouve rien."}, {"id": "T06", "fam": "T", "famille": "Argumenter", "pts": 2, "q": "À quoi sert un qualificatif (« probablement », « dans ces conditions ») ?", "options": ["À dire honnêtement la portée de la conclusion", "À éviter de conclure", "À allonger le texte", "À cacher les données"], "bonne": 0, "expl": "Un qualificatif précis protège contre la sur-généralisation."}, {"id": "T07", "fam": "T", "famille": "Argumenter", "pts": 3, "q": "Votre matrice pondérée donne le même classement quel que soit le poids des critères. Que dire ?", "options": ["Les poids sont inutiles", "Le résultat résiste au test de sensibilité ; les scores restent à sourcer", "Les scores sont forcément exacts", "L'analyse est terminée sans réserve"], "bonne": 1, "expl": "Un classement stable est plus solide, mais il repose toujours sur des scores à vérifier."}, {"id": "T08", "fam": "T", "famille": "Argumenter", "pts": 3, "q": "Pourquoi chercher soi-même les objections à sa recommandation ?", "options": ["Pour les cacher", "Pour allonger la présentation", "Pour y répondre avant le public et gagner en crédibilité", "Pour changer de sujet"], "bonne": 2, "expl": "Anticiper les objections montre que l'on a regardé les limites de sa propre proposition."}], "injects": [{"id": "I1", "repere": "H+0 · 6 h 50", "titre": "Le TMS est à l'arrêt", "contexte": "60 conducteurs sont sur le quai, aucune tournée n'est affichée. Trois grands clients attendent des livraisons avant 9 h. La cause est inconnue ; l'équipe informatique est en diagnostic.", "questions": [{"q": "À qui adressez-vous un message en premier ?", "options": [["Les clients : les prévenir d'un retard", 2, "Utile, mais les conducteurs sur le quai doivent d'abord savoir quoi faire."], ["Les salariés (conducteurs et exploitation) : consigne immédiate", 3, "Ce sont eux qui doivent agir tout de suite ; ils attendent une consigne."], ["Le public sur les réseaux : prendre les devants", 0, "Rien ne justifie de s'adresser au public avant les personnes concernées."], ["La direction : l'alerter", 1, "Nécessaire en parallèle, mais la direction est déjà dans la cellule de crise."]]}, {"q": "Quel message envoyez-vous aux conducteurs ?", "options": [["« Panne du TMS. Restez au quai. Prochain point à 7 h 30 avec la marche à suivre. »", 3, "Fait, consigne et prochain point daté : le trio d'un bon message de crise."], ["« Tout va bien, on gère, continuez. »", -1, "Inexact : rien ne fonctionne. Le message perd en crédibilité."], ["« Panne du TMS. Aucune information pour l'instant. »", 1, "Honnête, mais sans consigne ni prochain point."], ["« Panne du TMS, c'est la faute de l'informatique, on attend. »", 0, "Chercher un coupable ne fait pas avancer et dresse les équipes."]]}]}, {"id": "I2", "repere": "H+3 · 9 h 50", "titre": "Une vidéo circule", "contexte": "Un conducteur a publié une vidéo : « Arrêtés depuis trois heures. » Le client le plus important appelle, inquiet. La cause est identifiée : un serveur de base de données est en défaut ; un retour est estimé à 14 h, avec incertitude.", "questions": [{"q": "Qui traitez-vous en priorité ?", "options": [["Le public sur les réseaux : démentir la vidéo", 1, "La vidéo est vraie : démentir serait faux et aggraverait la situation."], ["Les salariés : rappeler la règle de publication", 2, "À faire, sans ton punitif, mais le client attend une réponse."], ["Le client le plus important", 3, "Il est directement touché et a appelé : il passe avant la rumeur."], ["L'assureur : déclarer le sinistre", 0, "Pas urgent à cette heure."]]}, {"q": "Que dites-vous au client ?", "options": [["« Retour à la normale dans une heure. »", -1, "Promesse non fondée : si elle est fausse, la confiance s'effondre."], ["« Pas de commentaire. »", 0, "Le client conclut que vous cachez quelque chose."], ["« Retard dû à un incident technique, nous nous excusons. »", 1, "Poli mais vague : aucune information utile."], ["« Le TMS est en panne depuis 6 h 50. Livraisons de ce matin décalées. Retour estimé à 14 h, avec incertitude ; je vous confirme à 12 h et traite vos urgences par téléphone. »", 3, "Faits, estimation honnête, prochain point daté, solution pour les urgences."]]}]}, {"id": "I3", "repere": "H+24 · mercredi 7 h", "titre": "La presse appelle", "contexte": "Le service est rétabli depuis 15 h hier. Trois tournées sur 20 sont encore retardées. La presse locale demande : « Combien de colis perdus ? Des données clients ont-elles fuité ? » Vos faits : aucun colis perdu ; aucune trace de fuite à ce stade, mais l'analyse n'est pas terminée.", "questions": [{"q": "Qui répond à la presse ?", "options": [["Un porte-parole désigné, avec des éléments validés", 3, "Une voix unique évite les contradictions."], ["Personne : ne pas décrocher", 0, "Le silence laisse la place aux rumeurs."], ["Le prestataire du TMS en direct", 1, "Il peut éclairer la technique, mais la parole de l'entreprise doit être la vôtre."], ["Le premier conducteur disponible", -1, "Un conducteur n'a pas les faits validés."]]}, {"q": "Que dit-il sur les données ?", "options": [["« Aucune donnée n'a fuité. »", -1, "Non établi : si l'analyse montre le contraire, la crédibilité est perdue."], ["« C'est un acte de malveillance. »", -1, "Non établi également."], ["« Panne de 6 h 50 à 15 h ; aucun colis perdu ; l'analyse est en cours pour exclure tout impact sur les données ; résultat communiqué d'ici vendredi. »", 3, "Ce qui est sûr, ce qui est en cours, et une échéance."], ["« Nous ne communiquons pas. »", 0, "Refus pur : la presse écrira sans vos faits."]]}]}, {"id": "I4", "repere": "H+72 · vendredi", "titre": "Le client menace", "contexte": "Le prestataire du TMS reconnaît une mise à jour non testée. Le client le plus important évoque une clause de pénalité et menace de réduire ses volumes. Vous préparez votre réponse.", "questions": [{"q": "Par quel canal répondez-vous au client ?", "options": [["Un e-mail générique", 0, "Impersonnel pour un client critique."], ["Attendre qu'il relance", -1, "Il verra l'inaction comme un mépris."], ["Un communiqué public", 0, "Hors sujet : le client attend un échange direct."], ["Un appel de la directrice, puis un courrier de confirmation", 3, "Personnel, rapide, avec une trace écrite."]]}, {"q": "Quel contenu donner à cet échange ?", "options": [["Rejeter la faute sur le prestataire", -1, "Le client a contracté avec TransLor, pas avec le prestataire."], ["Causes, mesures datées (test avant mise à jour, mode de secours manuel en moins de 30 minutes) et discussion d'un geste commercial", 3, "Faits, mesures chiffrées et datées, ouverture sur la réparation."], ["Une remise immédiate, sans analyse", 0, "Une réponse commerciale sans explication ni plan."], ["Des excuses sans plan", 1, "Nécessaires, insuffisantes."]]}]}, {"id": "I5", "repere": "J+30 · retour d'expérience", "titre": "Tirer les leçons", "contexte": "Un mois après la panne, la direction veut un retour d'expérience partagé avec toute l'entreprise, et un dispositif durable.", "questions": [{"q": "Que doit contenir le retour d'expérience ?", "options": [["Les faits, les causes, ce qui a marché ou non, des actions (qui, quoi, quand), sans coupable", 3, "Un retour d'expérience utile est factuel, sans coupable, avec des actions datées."], ["Seulement les bonnes décisions", 1, "Incomplet : on apprend aussi des erreurs."], ["Rien : la page est tournée", 0, "On répétera les mêmes erreurs."], ["Le nom du responsable", -1, "La recherche de coupable bloque la remontée d'informations."]]}, {"q": "Quel dispositif de communication pérenne mettez-vous en place ?", "options": [["Un e-mail annuel de rappel", 1, "Insuffisant."], ["Un nouvel outil de messagerie", 0, "Un outil ne remplace ni les rôles ni les messages prêts."], ["Aucun dispositif", 0, "Le prochain incident repartira de zéro."], ["Un plan de crise : annuaire, canal hors bande (SMS), messages pré-rédigés, porte-parole", 3, "Prêt à l'emploi le jour où le TMS tombe."]]}]}], "publics": [["Salariés", "Conducteurs, exploitation, support"], ["Clients", "Grands comptes et clients touchés"], ["Direction", "Directrice et comité de direction"], ["Public", "Réseaux sociaux, presse locale"], ["Partenaires", "Prestataire du TMS, assureur"]], "scenario": "Mardi 6 h 50. Le logiciel de tournées (TMS) de TransLor est inaccessible. 60 conducteurs attendent sur le quai, 20 tournées doivent partir, trois grands clients attendent leurs livraisons avant 9 h. Cause inconnue. Vous êtes la cellule de communication de crise : à chaque inject, répondez en équipe (2 décisions).", "titres": [[0, "Communicant en herbe"], [12, "Chargé de communication"], [20, "Directeur de la communication"], [26, "Porte-parole de l'année"]], "familles": {"R": "Chercher l'information", "V": "Évaluer et valider", "T": "Argumenter", "G": "Argumenter et informer"}, "sujets": [["Passkeys", "Faut-il remplacer les mots de passe par des passkeys ?"], ["Gestionnaire de mots de passe", "Faut-il un gestionnaire de mots de passe d'entreprise ?"], ["Double authentification", "SMS, application ou clé physique pour la double authentification ?"], ["Sauvegarde", "Cloud, disque local ou les deux (règle 3-2-1) ?"], ["IA générative au travail", "L'autoriser, l'encadrer ou l'interdire ?"], ["Télétravail et productivité", "L'effet du télétravail sur la productivité est-il établi ?"], ["Télétravail et accès", "VPN ou accès par navigateur sécurisé ?"], ["Hébergement", "Cloud public, hébergeur local ou serveur interne ?"], ["Ordinateurs personnels (BYOD)", "Faut-il autoriser les ordinateurs personnels au travail ?"], ["Sensibilisation au phishing", "Formation, simulations d'attaque, ou les deux ?"], ["Mises à jour automatiques", "Activer partout ou tester d'abord ?"], ["Logiciel libre ou propriétaire", "Bureautique et messagerie : lequel choisir ?"], ["Low-code", "Low-code ou développement classique pour des outils internes ?"], ["Microservices ou monolithe", "Quelle architecture pour une PME ?"], ["Empreinte du numérique", "Quels leviers pour réduire l'empreinte environnementale de l'informatique d'une PME ?"], ["Motorisation de la flotte", "Électrique, bioGNV ou HVO pour les livraisons ?"], ["Chiffrement des disques", "Chiffrer les portables : utile, et à quel coût ?"], ["Messagerie d'équipe", "Réseau social interne ou messagerie d'équipe pour faire circuler l'information ?"], ["Cahier des charges ou agile", "Quelle méthode pour un projet interne ?"]], "ordre": ["F0", "EX1", "EX2", "F1", "EX3", "EX4", "EX5", "EX6", "F2", "EX7", "EX8", "F3", "EX9", "EX10", "EX11", "F4", "EX12", "EX13", "F5", "EX14", "F6", "EX15", "EX16", "EX17", "EX18", "EX19", "EX20", "F7", "EX21", "EX22", "EX23", "EX24", "EX25", "F8", "EX26", "EX27", "EX28", "EX29", "F9"], "annexe": ["AX7", "AF3", "AX8", "AX9", "AX12", "AX13", "AX14", "AX10", "AF5", "AF7", "AX22", "AX23"]};
